import { useEffect } from 'react'

import { focusableWithin } from '../../lib/focusableWithin'

interface GridFocusTrapOptions {
  /** Opt in from dialogs only. Inline grids must stay in the page tab order. */
  trapFocus?: boolean
  gridRef: React.RefObject<HTMLElement>
}

export function useGridFocusTrap({ trapFocus = true, gridRef }: GridFocusTrapOptions) {
  useEffect(() => {
    const grid = gridRef.current
    if (!trapFocus || !grid) return

    function onKeyDown(event: KeyboardEvent) {
      if (event.key !== 'Tab' || !grid) return
      const cells = focusableWithin(grid)
      if (cells.length === 0) return
      const first = cells[0]
      const last = cells[cells.length - 1]
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault()
        last.focus()
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault()
        first.focus()
      }
    }

    grid.addEventListener('keydown', onKeyDown)
    return () => {
      grid.removeEventListener('keydown', onKeyDown)
    }
  }, [trapFocus, gridRef])
}

