import { render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { describe, expect, it, vi } from 'vitest'

import { SkillMatrix } from './SkillMatrix'

const rows = [
  { id: 'sk-201', skill: 'Manual handling refresher', levelsByMember: { 'mem-11': 3, 'mem-12': 1 } },
  { id: 'sk-202', skill: 'Safeguarding level 2', levelsByMember: { 'mem-11': 2, 'mem-12': 2 } },
]

describe('SkillMatrix focus behaviour', () => {
  it('lets Tab leave an inline grid and reach the next control on the page', async () => {
    const user = userEvent.setup()
    render(
      <div>
        <SkillMatrix rows={rows} onCellOpen={vi.fn()} />
        <button type="button">Export matrix</button>
      </div>,
    )

    await user.tab()
    expect(screen.getAllByRole('gridcell')[0]).toHaveFocus()
    await user.tab()
    expect(screen.getByRole('button', { name: 'Export matrix' })).toHaveFocus()
  })

  it('still cycles inside the grid when a dialog opts in', async () => {
    const user = userEvent.setup()
    render(
      <div>
        <SkillMatrix rows={rows} trapFocus onCellOpen={vi.fn()} />
        <button type="button">Export matrix</button>
      </div>,
    )

    await user.tab()
    await user.tab()
    expect(screen.getByRole('button', { name: 'Export matrix' })).not.toHaveFocus()
  })
})

