  return {
    id: 'extra-' + input.dueDate,
    kind: 'extra',
    amountCents: input.amountCents,
    dueDate: input.dueDate,
    amountLabel: formatMoney(input.amountCents, input.currency, input.locale),
    dueDateLabel: formatDueDate(input.dueDate, input.locale),
  }
}

