      </span>
      <span className="text-sm text-stone-600 dark:text-stone-400">
        {entry.status === 'blocked' ? 'Blocked' : 'Clear'}
      </span>
      <button
        type="button"
        onClick={() => onBlock(entry.id)}
        className="min-h-11 rounded-lg border border-stone-300 px-4 py-2 text-base font-medium text-stone-900 hover:bg-stone-50 focus-visible:ring-2 focus-visible:ring-lime-700 focus-visible:ring-offset-2 active:scale-[0.98] dark:border-stone-700 dark:text-stone-100 dark:hover:bg-stone-900"
      >
        Mark blocked
      </button>
    </li>
  )
})

export function CulvertChecklist({ culverts }: CulvertChecklistProps) {
  const [entries, setEntries] = useState(() => new Map(culverts.map((culvert) => [culvert.id, culvert])))

  const markBlocked = useCallback((culvertId: string) => {
    setEntries((current) => {
      const next = new Map(current)
      const entry = next.get(culvertId)
      if (entry) {
        entry.status = 'blocked'
        entry.blockedAt = new Date().toISOString()
      }
      return next
    })
  }, [])

  return (
    <ul className="flex flex-col">
      {Array.from(entries.values()).map((entry) => (
        <CulvertRow key={entry.id} entry={entry} onBlock={markBlocked} />
      ))}
    </ul>
  )
}

