import { fireEvent, render, screen, waitFor } from '@testing-library/react'
import { afterEach, describe, expect, it, vi } from 'vitest'

import { ReagentPriorityList } from './ReagentPriorityList'
import { saveReagentPriority } from './reagentApi'

vi.mock('./reagentApi', () => ({ saveReagentPriority: vi.fn().mockResolvedValue(undefined) }))

const savePriority = vi.mocked(saveReagentPriority)

const reagents = [
  { sku: 'RG-4410', name: 'Sodium citrate 3.2 percent', onHand: 14 },
  { sku: 'RG-4418', name: 'Tris buffer pH 7.4', onHand: 6 },
  { sku: 'RG-4425', name: 'Proteinase K 20 mg/mL', onHand: 3 },
]

afterEach(() => {
  vi.clearAllMocks()
})

describe('ReagentPriorityList', () => {
  it('saves one reorder when the tablet fires dragend and pointerup for the same drag', async () => {
    const onReordered = vi.fn()
    render(<ReagentPriorityList reagents={reagents} onReordered={onReordered} />)
    const rows = screen.getAllByRole('listitem')

    fireEvent.dragStart(rows[2])
    fireEvent.dragOver(rows[0])
    fireEvent.dragEnd(rows[2])
    fireEvent.pointerUp(rows[2])

    expect(savePriority).toHaveBeenCalledTimes(1)
    expect(savePriority).toHaveBeenCalledWith(['RG-4425', 'RG-4410', 'RG-4418'])
    await waitFor(() => expect(onReordered).toHaveBeenCalledTimes(1))
  })

  it('still saves a plain mouse drag that only ends with dragend', async () => {
    const onReordered = vi.fn()
    render(<ReagentPriorityList reagents={reagents} onReordered={onReordered} />)
    const rows = screen.getAllByRole('listitem')

    fireEvent.dragStart(rows[0])
    fireEvent.dragOver(rows[1])
    fireEvent.dragEnd(rows[0])

    expect(savePriority).toHaveBeenCalledTimes(1)
    expect(savePriority).toHaveBeenCalledWith(['RG-4418', 'RG-4410', 'RG-4425'])
    await waitFor(() => expect(onReordered).toHaveBeenCalledTimes(1))
  })
})

