import { useState } from 'react'

import { ChannelPicker } from './ChannelPicker'
import type { CampaignAlert, Channel } from './campaignTypes'

interface AlertCenterProps {
  alerts: CampaignAlert[]
  channels: Channel[]
}

function isSelected(alert: CampaignAlert, channel: Channel | null) {
  return channel === null || alert.channel === channel
}

export function AlertCenter({ alerts, channels }: AlertCenterProps) {
  const [selectedChannel, setSelectedChannel] = useState<Channel | null>(null)
  const visible = alerts.filter((alert) => isSelected(alert, selectedChannel))

  return (
    <section className="flex flex-col gap-6">
      <div className="flex items-end justify-between gap-6">
        <h2 className="text-2xl font-semibold leading-tight text-zinc-900 dark:text-zinc-100">Campaign alerts</h2>
        <ChannelPicker channels={channels} value={selectedChannel} onChange={setSelectedChannel} />
      </div>
      {visible.length === 0 ? (
        <p className="text-base leading-relaxed text-zinc-700 dark:text-zinc-300">
          No alerts on this channel. Clear the channel filter to see every campaign alert.
        </p>
      ) : (
        <ul className="flex flex-col gap-2">
          {visible.map((alert) => (
            <li key={alert.id} className="flex items-start justify-between gap-4 rounded-lg border border-zinc-200 p-4 dark:border-zinc-800">
              <p className="min-w-0 text-base leading-relaxed text-zinc-900 dark:text-zinc-100">{alert.message}</p>
              <span className="shrink-0 text-sm font-medium text-zinc-600 dark:text-zinc-400">{alert.channel.label}</span>
            </li>
          ))}
        </ul>
      )}
    </section>
  )
}

