import { act, renderHook, waitFor } from '@testing-library/react'
import { beforeEach, describe, expect, it, vi } from 'vitest'

import { fetchCohortMembers, removeCohortMember } from './cohortApi'
import { useCohortMembers } from './useCohortMembers'
import type { CohortMember } from './types'

vi.mock('./cohortApi', () => ({
  fetchCohortMembers: vi.fn(),
  removeCohortMember: vi.fn(),
}))

const dunbar: CohortMember = { practiceId: 'p-114', practiceName: 'Dunbar Kennels' }
const brackley: CohortMember = { practiceId: 'p-207', practiceName: 'Brackley Road Vets' }

function deferred<T>() {
  let resolve!: (value: T) => void
  const promise = new Promise<T>((settle) => {
    resolve = settle
  })
  return { promise, resolve }
}

describe('useCohortMembers', () => {
  beforeEach(() => {
    vi.mocked(fetchCohortMembers).mockReset()
    vi.mocked(removeCohortMember).mockReset()
    vi.mocked(removeCohortMember).mockResolvedValue(undefined)
  })

  it('ignores a refetch that was already in flight when a practice was removed', async () => {
    const firstLoad = deferred<CohortMember[]>()
    const staleLoad = deferred<CohortMember[]>()
    vi.mocked(fetchCohortMembers)
      .mockReturnValueOnce(firstLoad.promise)
      .mockReturnValueOnce(staleLoad.promise)
      .mockResolvedValue([brackley])

    const { result } = renderHook(() => useCohortMembers('kennel-club-beta'))
    await act(async () => {
      firstLoad.resolve([dunbar, brackley])
    })
    await waitFor(() => expect(result.current.members).toHaveLength(2))

    act(() => {
      void result.current.refresh()
    })
    await act(async () => {
      await result.current.remove('p-114')
    })
    await act(async () => {
      staleLoad.resolve([dunbar, brackley])
    })

    expect(result.current.members.map((member) => member.practiceId)).toEqual(['p-207'])
  })

  it('still applies the refetch that the removal itself starts', async () => {
    vi.mocked(fetchCohortMembers)
      .mockResolvedValueOnce([dunbar, brackley])
      .mockResolvedValue([brackley])

    const { result } = renderHook(() => useCohortMembers('kennel-club-beta'))
    await waitFor(() => expect(result.current.members).toHaveLength(2))

    await act(async () => {
      await result.current.remove('p-114')
    })

    expect(result.current.members).toEqual([brackley])
  })
})

