import { useEffect, useState } from 'react'

import type { PreferenceKey, PreferenceValues } from './types'

const values: PreferenceValues = {
  units: 'metric',
  timeFormat: 'utc',
  decomProfile: 'ccsds-b',
}

const listeners = new Map<PreferenceKey, Set<() => void>>()

export function getPreference<K extends PreferenceKey>(key: K): PreferenceValues[K] {
  return values[key]
}

export function setPreference<K extends PreferenceKey>(key: K, value: PreferenceValues[K]) {
  values[key] = value
  listeners.get(key)?.forEach((listener) => listener())
}

export function subscribe(key: PreferenceKey, listener: () => void) {
  const forKey = listeners.get(key) ?? new Set<() => void>()
  forKey.add(listener)
  listeners.set(key, forKey)
}

export function unsubscribe(key: PreferenceKey) {
  listeners.delete(key)
}

export function usePreference<K extends PreferenceKey>(key: K) {
  const [value, setValue] = useState(() => getPreference(key))

  useEffect(() => {
    function onChange() {
      setValue(getPreference(key))
    }

    subscribe(key, onChange)
    return () => unsubscribe(key)
  }, [key])

  return value
}

