import { useFleetStore } from '../../stores/fleetStore'

interface Station {
  id: string
  name: string
  capacity: number
  docked: number
  lastRebalancedAt: string
}

const OVERFULL_RATIO = 0.9

export function RebalanceQueue() {
  const stations = useFleetStore((s) => s.stations)
  const overfull = (stations as Station[])
    .filter((s) => s.docked >= s.capacity * OVERFULL_RATIO)
    .sort((a, b) => b.lastRebalancedAt.localeCompare(a.lastRebalancedAt))

  if (overfull.length === 0) {
    return (
      <p className="p-4 text-base text-zinc-600">
        No stations need rebalancing right now. Next sync runs in a few minutes.
      </p>
    )
  }

  return (
    <ol className="flex flex-col gap-2">
      {overfull.map((station) => (
        <li key={station.id} className="flex items-center justify-between rounded-md border border-zinc-200 p-4">
          <span className="min-w-0 truncate text-base font-medium text-zinc-900" title={station.name}>
            {station.name}
          </span>
          <span className="text-sm tabular-nums text-zinc-600">
            {station.docked}/{station.capacity} docks
          </span>
        </li>
      ))}
    </ol>
  )
}

