    expect(parseThreshold('12,5', 'de-DE')).toBe(12.5)
  })

  it('reads the same limit typed in Denver', () => {
    expect(parseThreshold('12.5', 'en-US')).toBe(12.5)
  })

  it('round trips whatever the field writes back into the box', () => {
    expect(formatThreshold(12.5, 'de-DE')).toBe('12,5')
    expect(parseThreshold(formatThreshold(12.5, 'de-DE'), 'de-DE')).toBe(12.5)
