import { useInlineSave } from './useInlineSave'

afterEach(() => {
  vi.useRealTimers()
})

describe('useInlineSave', () => {
  it('does not autosave when the caller passes no options', () => {
    vi.useFakeTimers()
    const save = vi.fn().mockResolvedValue(undefined)
    const { result } = renderHook(() => useInlineSave('12 Mar to 19 Mar', save, undefined))

    act(() => {
      result.current.setValue('12 Mar to 1')
    })
    act(() => {
      vi.advanceTimersByTime(5000)
    })

    expect(save).not.toHaveBeenCalled()
    expect(result.current.status).toBe('idle')
  })

  it('debounces at the interval the caller asked for', async () => {
    vi.useFakeTimers()
    const save = vi.fn().mockResolvedValue(undefined)
    const { result } = renderHook(() => useInlineSave('PO 4471', save, { debounceMs: 1200 }))

    act(() => {
      result.current.setValue('PO 4471-B')
    })
    act(() => {
      vi.advanceTimersByTime(1199)
    })
    expect(save).not.toHaveBeenCalled()

    act(() => {
      vi.advanceTimersByTime(1)
    })
    expect(save).toHaveBeenCalledWith('PO 4471-B')
  })

  it('keeps the 700ms default when options are given without an interval', () => {
    vi.useFakeTimers()
    const save = vi.fn().mockResolvedValue(undefined)
    const { result } = renderHook(() => useInlineSave('Kerb side, no crane', save, {}))

    act(() => {
      result.current.setValue('Kerb side, no crane, ring the yard')
    })
    act(() => {
      vi.advanceTimersByTime(700)
    })

    expect(save).toHaveBeenCalledWith('Kerb side, no crane, ring the yard')
  })
})

