import { useState } from 'react'

import type { Bay } from './types'

interface BayOccupancyListProps {
  bays: Bay[]
  onOpenBay: (bayId: string) => void
}

const PAGE_SIZE = 12
const navClass =
  'rounded-lg border border-zinc-300 px-4 py-2 text-sm font-medium text-zinc-900 transition-colors hover:bg-zinc-50 focus-visible:ring-2 focus-visible:ring-teal-700 focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 motion-reduce:transition-none dark:border-zinc-700 dark:text-zinc-100 dark:hover:bg-zinc-900'

export function BayOccupancyList({ bays, onOpenBay }: BayOccupancyListProps) {
  const [page, setPage] = useState(0)

  if (bays.length === 0) {
    return (
      <p className="rounded-lg border border-zinc-200 p-6 text-base text-zinc-700 dark:border-zinc-800 dark:text-zinc-300">
        No bays mapped for this block. Import the block layout to start tracking occupancy.
      </p>
    )
  }

  const pageCount = Math.ceil(bays.length / PAGE_SIZE)
  const start = page * PAGE_SIZE
  const visible = bays.slice(start, start + PAGE_SIZE)

  return (
    <div className="flex flex-col gap-6">
      <ul className="flex flex-col gap-2">
        {visible.map((bay) => (
          <li key={bay.id}>
            <button
              type="button"
              onClick={() => onOpenBay(bay.id)}
              className="flex min-h-11 w-full items-center justify-between gap-4 rounded-lg border border-zinc-200 px-4 py-3 text-left transition-colors hover:bg-zinc-50 focus-visible:ring-2 focus-visible:ring-teal-700 focus-visible:ring-offset-2 active:scale-[0.98] motion-reduce:transition-none dark:border-zinc-800 dark:hover:bg-zinc-900"
            >
              <span className="text-base font-medium tabular-nums text-zinc-900 dark:text-zinc-100">
                Bay {bay.bayIndex + 1}
              </span>
              <span
                className="min-w-0 truncate text-sm tabular-nums text-zinc-600 dark:text-zinc-400"
                title={bay.containerId ?? 'Open bay'}
              >
                {bay.containerId ?? 'Open bay'}
              </span>
            </button>
          </li>
        ))}
      </ul>
      <div className="flex items-center justify-between gap-4">
        <button type="button" onClick={() => setPage(page - 1)} disabled={page === 0} className={navClass}>
          Previous
        </button>
        <span className="text-sm tabular-nums text-zinc-600 dark:text-zinc-400">
          Bays {start + 1} to {start + visible.length} of {bays.length}
        </span>
        <button
          type="button"
          onClick={() => setPage(page + 1)}
          disabled={page >= pageCount - 1}
          className={navClass}
        >
          Next
        </button>
      </div>
    </div>
  )
}

