export function PortOutExportButton({ filters, orderCount }: PortOutExportButtonProps) {
  const [pending, setPending] = useState(false)

  function onExport() {
    setPending(true)
    startExport()
    setPending(false)
  }

  async function startExport() {
    const downloadUrl = await requestPortOutExport(filters, ['orderId', 'status'])
    window.location.assign(downloadUrl)
  }

  return (
    <div className="flex flex-col gap-2">
      <button
        type="button"
        onClick={onExport}
        disabled={pending || orderCount === 0}
        className="rounded-md bg-sky-700 px-4 py-2 text-base font-medium text-white transition-colors hover:bg-sky-800 focus-visible:ring-2 focus-visible:ring-sky-600 focus-visible:ring-offset-2 active:scale-[0.98] disabled:pointer-events-none disabled:opacity-50 motion-reduce:transition-none dark:bg-sky-600 dark:hover:bg-sky-500"
      >
        {pending ? 'Preparing export' : `Export ${orderCount} port-out orders`}
      </button>
      <p className="text-sm leading-relaxed text-zinc-600 dark:text-zinc-400">
        Covers every order matching the filters above.
      </p>
    </div>
  )
}

import type { PortOutFilters } from './types'

export async function requestPortOutExport(filters: PortOutFilters, columns: string[]): Promise<string> {
  const query = new URLSearchParams({
    status: filters.status,
    donorCarrier: filters.donorCarrier ?? '',
    columns: columns.join(','),
  })

  const response = await fetch(`/api/port-outs/export?${query.toString()}`, { method: 'POST' })
  if (!response.ok) {
    throw new Error(`The export service answered ${response.status}`)
  }

  const payload = (await response.json()) as { downloadUrl: string }
  return payload.downloadUrl
}

