import { act, renderHook } from '@testing-library/react'
import { afterEach, describe, expect, it, vi } from 'vitest'

import { saveRoundNote } from './roundsApi'
import { useRoundDraft } from './useRoundDraft'

vi.mock('./roundsApi', () => ({ saveRoundNote: vi.fn() }))

const saveRoundNoteMock = vi.mocked(saveRoundNote)

afterEach(() => {
  vi.clearAllMocks()
})

describe('useRoundDraft', () => {
  it('flushes the pending note when the editor unmounts', async () => {
    saveRoundNoteMock.mockResolvedValue(undefined)
    const onSaveError = vi.fn()
    const { result, unmount } = renderHook(() =>
      useRoundDraft({ roundId: 'RND-118', initialNote: 'Gate code 4417', onSaveError }),
    )

    act(() => {
      result.current.edit('Gate code 4417, bins behind the hedge')
    })
    unmount()

    await vi.waitFor(() => {
      expect(saveRoundNoteMock).toHaveBeenCalledWith('RND-118', 'Gate code 4417, bins behind the hedge')
    })
    expect(onSaveError).not.toHaveBeenCalled()
  })

  it('reports the failure when the unmount flush is rejected', async () => {
    saveRoundNoteMock.mockRejectedValue(new Error('Network request failed'))
    const onSaveError = vi.fn()
    const { result, unmount } = renderHook(() =>
      useRoundDraft({ roundId: 'RND-204', initialNote: 'Assisted collection, 12 Larch Way', onSaveError }),
    )

    act(() => {
      result.current.edit('Assisted collection, 12 Larch Way, side gate')
    })
    unmount()

    await vi.waitFor(() => {
      expect(onSaveError).toHaveBeenCalledWith('Round note did not save. Check the depot connection.')
    })
  })
})

