import { useRef } from 'react'

import { PatchList } from './PatchList'
import { XIcon } from '../icons'
import type { Patch } from '../types/patch'

interface PatchDrawerProps {
  patches: Patch[]
  open: boolean
  onClose: () => void
  onLoadPatch: (patchId: string) => void
}

const EXIT_KEYFRAMES: Keyframe[] = [
  { opacity: 1, transform: 'translateX(0)' },
  { opacity: 0, transform: 'translateX(100%)' },
]

export function PatchDrawer({ patches, open, onClose, onLoadPatch }: PatchDrawerProps) {
  const panelRef = useRef<HTMLDivElement>(null)

  function handleClose() {
    panelRef.current?.animate(EXIT_KEYFRAMES, { duration: 160, easing: 'ease-in', fill: 'forwards' }).finished.then(() => {
      onClose()
    })
  }

  if (!open) return null

  return (
    <div
      ref={panelRef}
      role="dialog"
      aria-label="Patch library"
      className="fixed right-0 top-0 z-40 h-dvh w-80 border-l border-zinc-200 bg-white p-6 dark:border-zinc-800 dark:bg-zinc-950"
    >
      <button
        type="button"
        onClick={handleClose}
        aria-label="Close patch library"
        className="min-h-11 rounded-md p-2 text-zinc-500 hover:bg-zinc-100 focus-visible:ring-2 focus-visible:ring-orange-500 focus-visible:ring-offset-2 dark:text-zinc-400 dark:hover:bg-zinc-900"
      >
        <XIcon />
      </button>
      <PatchList patches={patches} onLoadPatch={onLoadPatch} />
    </div>
  )
}

