  onNavigate: (stopId: string) => void
}

export function RouteStopList({ stops, onNavigate }: RouteStopListProps) {
  if (stops.length === 0) {
    return (
      <p className="rounded-lg border border-zinc-200 p-6 text-base text-zinc-700 dark:border-zinc-800 dark:text-zinc-300">
        No stops on this run yet. Stops appear here once dispatch releases the manifest.
      </p>
    )
  }

  return (
    <ol className="flex flex-col gap-2">
      {stops.map((stop, index) => (
        <li key={stop.id}>
          <button
            type="button"
            onClick={() => onNavigate(stop.id)}
            className="flex min-h-11 w-full items-center gap-4 rounded-lg border border-zinc-200 px-4 py-3 text-left transition-colors hover:bg-zinc-50 focus-visible:ring-2 focus-visible:ring-indigo-700 focus-visible:ring-offset-2 active:scale-[0.98] motion-reduce:transition-none dark:border-zinc-800 dark:hover:bg-zinc-900"
          >
