              <span className="block truncate text-base font-medium text-zinc-900 dark:text-zinc-100" title={stop.consignee}>
                {stop.consignee}
              </span>
              <span className="block text-sm tabular-nums text-zinc-600 dark:text-zinc-400">
                {stop.windowStart} to {stop.windowEnd}
              </span>
            </span>
