import { useState } from 'react'

interface SignatureConfirmDialogProps {
  participantId: string
  studyName: string
  onConfirm: () => Promise<void>
  onCancel: () => void
}

export function SignatureConfirmDialog({ participantId, studyName, onConfirm, onCancel }: SignatureConfirmDialogProps) {
  const [error, setError] = useState<string | null>(null)

  async function handleConfirm() {
    setError(null)
    try {
      await onConfirm()
    } catch {
      setError("We could not file your consent. Check your connection and try again.")
    }
  }

  return (
    <div className="fixed inset-0 z-40 flex items-center justify-center bg-zinc-950/60 p-4">
      <div role="dialog" aria-modal="true" aria-labelledby="consent-heading" className="w-full max-w-md rounded-lg bg-white p-6 shadow-lg dark:bg-zinc-900">
