        <p className="mt-2 text-base leading-relaxed text-zinc-700 dark:text-zinc-300">Signing records consent for participant {participantId}. You can withdraw at any study visit.</p>
        {error ? (
          <p role="alert" className="mt-4 text-sm text-red-700 dark:text-red-400">{error}</p>
        ) : null}
        <div className="mt-6 flex justify-end gap-2">
          <button type="button" onClick={onCancel} className="rounded-lg border border-zinc-300 px-4 py-2 text-sm font-medium text-zinc-700 hover:bg-zinc-100 focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-offset-2 dark:border-zinc-700 dark:text-zinc-300 dark:hover:bg-zinc-800">
            Cancel
          </button>
          <button type="button" onClick={handleConfirm} className="rounded-lg bg-zinc-900 px-4 py-2 text-sm font-medium text-white hover:bg-zinc-800 focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-offset-2 active:scale-[0.98] dark:bg-zinc-100 dark:text-zinc-900">
