import type { Drive } from '../../types/drive'

interface DriveSummaryProps {
  drive: Drive
}

export function DriveSummary({ drive }: DriveSummaryProps) {
  const closes = new Date(drive.closesAt).toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
  })
  const pct = Math.min(100, Math.round((drive.pledgedLbs / drive.goalLbs) * 100))

  return (
    <section className="flex flex-col gap-4 rounded-lg border border-zinc-200 p-6 dark:border-zinc-800">
      <h2 className="text-xl font-semibold leading-tight text-zinc-900 dark:text-zinc-100">{drive.name}</h2>
      <p className="text-sm text-zinc-600 dark:text-zinc-400">Closes {closes}</p>
      <div className="h-2 w-full rounded-full bg-zinc-200 dark:bg-zinc-800">
        <div className="h-2 rounded-full bg-amber-600" style={{ width: `${pct}%` }} />
      </div>
      <p className="text-base text-zinc-700 dark:text-zinc-300">{drive.pledgedLbs} lbs pledged of {drive.goalLbs}</p>
    </section>
  )
}

