import { render, screen } from '@testing-library/react'
import { describe, expect, it } from 'vitest'

import { DriveSummary } from './DriveSummary'

const drive = {
  id: 'drv-2026-lent',
  name: 'Lenten shelf-stable drive',
  closesAt: '2026-03-14',
  goalLbs: 24000,
  pledgedLbs: 12480,
}

describe('DriveSummary', () => {
  it('formats a date-only close date in UTC so it does not slip a day', () => {
    render(<DriveSummary drive={drive} />)
    expect(screen.getByText('Closes Mar 14, 2026')).toBeInTheDocument()
  })

  it('groups pledged pounds with thousands separators', () => {
    render(<DriveSummary drive={drive} />)
    expect(screen.getByText('12,480 lbs pledged of 24,000')).toBeInTheDocument()
  })

  it('shows the pledge call to action when nothing is pledged yet', () => {
    render(<DriveSummary drive={{ ...drive, pledgedLbs: 0 }} />)
    expect(screen.getByText(/No pledges yet/)).toBeInTheDocument()
    expect(screen.getByRole('link', { name: 'Pledge food' })).toHaveAttribute('href', '/drives/drv-2026-lent/pledge')
  })
})

