import type { CachedSurgeSnapshot } from './types'

interface CachedSurgePanelProps {
  snapshot: CachedSurgeSnapshot
  onRefresh: () => void
}

const refreshClass =
  'self-start rounded-lg border border-zinc-300 px-4 py-2 text-sm font-medium text-zinc-900 transition-colors hover:bg-zinc-50 focus-visible:ring-2 focus-visible:ring-cyan-700 focus-visible:ring-offset-2 active:scale-[0.98] motion-reduce:transition-none dark:border-zinc-700 dark:text-zinc-100 dark:hover:bg-zinc-900'

export function CachedSurgePanel({ snapshot, onRefresh }: CachedSurgePanelProps) {
  const gaugeIds = Object.keys(snapshot.gaugeLevelsCm)

  return (
    <section className="flex flex-col gap-6 rounded-lg border border-zinc-200 p-6 dark:border-zinc-800">
      <header className="flex flex-col gap-2">
        <h2 className="text-2xl font-semibold leading-tight text-zinc-900 dark:text-zinc-100">
          {snapshot.harborName}
        </h2>
        <p className="text-sm text-zinc-600 dark:text-zinc-400">Offline copy stored {snapshot.cachedAt}</p>
      </header>
      <ul className="flex flex-col gap-2">
        {gaugeIds.map((gaugeId) => (
          <li key={gaugeId} className="flex items-center justify-between gap-4">
            <span className="min-w-0 truncate text-base text-zinc-700 dark:text-zinc-300" title={gaugeId}>
              {gaugeId}
            </span>
            <span className="text-base tabular-nums text-zinc-900 dark:text-zinc-100">
              {snapshot.gaugeLevelsCm[gaugeId]} cm
            </span>
          </li>
        ))}
      </ul>
      <button type="button" onClick={onRefresh} className={refreshClass}>
        Refresh from network
      </button>
    </section>
  )
}

