import { useLayoutEffect, useEffect, useRef, useState } from 'react'

import { ShiftRowSkeleton } from './ShiftRowSkeleton'
import { fetchShiftRows } from './staffingApi'
import type { ShiftRow } from './types'

interface StaffingBoardProps {
  stand: string
}

export function StaffingBoard({ stand }: StaffingBoardProps) {
  const [rows, setRows] = useState<ShiftRow[]>([])
  const [status, setStatus] = useState<'loading' | 'ready'>('loading')
  const activeStand = useRef(stand)

  useEffect(() => {
    activeStand.current = stand
  }, [stand])

  useLayoutEffect(() => {
    setStatus('loading')
    void fetchShiftRows(activeStand.current).then((next) => {
      setRows(next)
      setStatus('ready')
    })
  }, [stand])

  if (status === 'loading') {
    return (
      <ul aria-busy="true" aria-label="Loading shifts" className="flex flex-col gap-2">
        {[0, 1, 2, 3, 4].map((slot) => (
          <li key={slot}>
            <ShiftRowSkeleton />
          </li>
        ))}
      </ul>
    )
  }

  return (
    <ul className="flex flex-col gap-2">
      {rows.map((row) => (
        <li
          key={row.id}
          className="flex min-h-16 items-center gap-4 rounded-md border border-slate-200 px-4 py-3 dark:border-slate-800"
        >
          <span className="min-w-0 flex-1 truncate text-base text-slate-900 dark:text-slate-100" title={row.role}>
            {row.role}
          </span>
          <span className="text-sm tabular-nums text-slate-600 dark:text-slate-400">{row.startsAt}</span>
        </li>
      ))}
    </ul>
  )
}

