import { fireEvent, render, screen } from '@testing-library/react'
import { beforeEach, describe, expect, it, vi } from 'vitest'
import { PlanDropInput } from './PlanDropInput'

const createUrlSpy = vi.fn(() => 'blob:planvault/preview-1')

beforeEach(() => {
  createUrlSpy.mockClear()
  Object.defineProperty(URL, 'createObjectURL', { value: createUrlSpy, writable: true })
})

describe('PlanDropInput', () => {
  it('creates no object URLs for a rejected batch', () => {
    render(<PlanDropInput onAccepted={vi.fn()} />)
    const pdf = new File(['pdf-bytes'], 'level-2-structural.pdf', { type: 'application/pdf' })
    const dwg = new File(['dwg-bytes'], 'level-2-structural.dwg', { type: 'application/acad' })
    fireEvent.change(screen.getByLabelText('Add plan files'), { target: { files: [pdf, dwg] } })
    expect(screen.getByRole('alert').textContent).toContain('level-2-structural.dwg is not a supported plan format')
    expect(createUrlSpy).not.toHaveBeenCalled()
  })

  it('still previews and reports a clean batch', () => {
    const onAccepted = vi.fn()
    render(<PlanDropInput onAccepted={onAccepted} />)
    const pdf = new File(['pdf-bytes'], 'ground-floor.pdf', { type: 'application/pdf' })
    fireEvent.change(screen.getByLabelText('Add plan files'), { target: { files: [pdf] } })
    expect(onAccepted).toHaveBeenCalledWith([pdf])
    expect(screen.getByAltText('ground-floor.pdf preview')).toBeInTheDocument()
    expect(createUrlSpy).toHaveBeenCalledTimes(1)
  })
})

