import { useState } from 'react'

import type { DraftReading } from './types'

interface DraftSurveyPanelProps {
  surveyRef: string
  readings: DraftReading[]
  onApplyCorrection: (readingIds: string[]) => void
}

export function DraftSurveyPanel({ surveyRef, readings, onApplyCorrection }: DraftSurveyPanelProps) {
  const [selectedIds, setSelectedIds] = useState<string[]>([])

  function toggle(readingId: string) {
    setSelectedIds((current) =>
      current.includes(readingId) ? current.filter((id) => id !== readingId) : [...current, readingId],
    )
  }

  return (
    <section className="mx-auto flex min-h-dvh w-full max-w-7xl flex-col gap-6 p-6">
      <h1 className="text-2xl font-semibold leading-tight text-stone-900 dark:text-stone-100">
        Draft survey {surveyRef}
