            role="toolbar"
            aria-label="Bulk reading actions"
            className="fixed inset-x-0 bottom-0 z-40 flex flex-wrap items-center gap-4 border-t border-stone-200 bg-white p-4 dark:border-stone-800 dark:bg-stone-950"
          >
            <p className="text-base tabular-nums text-stone-700 dark:text-stone-300">
              {selectedIds.length} readings ticked
            </p>
            <button
              type="button"
              onClick={() => onApplyCorrection(selectedIds)}
              className="rounded-md bg-orange-800 px-4 py-2 text-base font-medium text-white transition-colors hover:bg-orange-900 focus-visible:ring-2 focus-visible:ring-orange-700 focus-visible:ring-offset-2 active:scale-[0.98] motion-reduce:transition-none dark:bg-orange-700 dark:hover:bg-orange-600"
            >
              Apply trim correction
            </button>
            <button
              type="button"
              onClick={() => setSelectedIds([])}
              className="rounded-md border border-stone-300 px-4 py-2 text-base font-medium text-stone-800 transition-colors hover:bg-stone-50 focus-visible:ring-2 focus-visible:ring-orange-700 focus-visible:ring-offset-2 dark:border-stone-700 dark:text-stone-200 dark:hover:bg-stone-900"
