import { render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { beforeEach, describe, expect, it, vi } from 'vitest'

import { AnnotationHistoryPanel } from './AnnotationHistoryPanel'

const mocks = vi.hoisted(() => ({
  undo: vi.fn(),
  redo: vi.fn(),
  revisions: [
    {
      id: 'ar-4409',
      summary: 'Traced the crack on bench 320 west to the ramp',
      author: 'Ingrid Solheim',
      revisedAt: '2026-03-14T08:20:00Z',
    },
    {
      id: 'ar-4402',
      summary: 'Marked the toe seepage patch below the catch bench',
      author: 'Kofi Mensah',
      revisedAt: '2026-03-11T15:05:00Z',
    },
  ],
}))

vi.mock('./useAnnotationHistory', () => ({
  useAnnotationHistory: () => ({ revisions: mocks.revisions, undo: mocks.undo, redo: mocks.redo }),
}))

describe('AnnotationHistoryPanel', () => {
  beforeEach(() => {
    mocks.undo.mockReset()
    mocks.redo.mockReset()
  })

  it('steps back through the annotation history on ctrl z', async () => {
    const user = userEvent.setup()
    render(<AnnotationHistoryPanel scanId="pw-2207" />)

    await user.keyboard('{Control>}z{/Control}')

    expect(mocks.undo).toHaveBeenCalledTimes(1)
    expect(mocks.redo).not.toHaveBeenCalled()
  })

  it('steps forward on ctrl shift z', async () => {
    const user = userEvent.setup()
    render(<AnnotationHistoryPanel scanId="pw-2207" />)

    await user.keyboard('{Control>}{Shift>}Z{/Shift}{/Control}')

    expect(mocks.redo).toHaveBeenCalledTimes(1)
  })

  it('undoes once per ctrl z after the compare dialog has been opened and closed', async () => {
    const user = userEvent.setup()
    render(<AnnotationHistoryPanel scanId="pw-2207" />)

    await user.click(screen.getByRole('button', { name: 'Compare with the 14 March revision' }))
    await user.keyboard('{Escape}')
    expect(screen.queryByRole('dialog')).not.toBeInTheDocument()

    await user.keyboard('{Control>}z{/Control}')

    expect(mocks.undo).toHaveBeenCalledTimes(1)
  })
})

