import { NoteCard } from './NoteCard'

interface InspectionNote {
  id: string
  hiveName: string
  summary: string
}

interface InspectionNoteListProps {
  initialNotes: InspectionNote[]
}

export function InspectionNoteList({ initialNotes }: InspectionNoteListProps) {
  const [notes, setNotes] = useState(initialNotes)
  const itemRefs = useRef<(HTMLLIElement | null)[]>([])

  function handleDelete(index: number) {
    const remaining = notes.filter((_, i) => i !== index)
    setNotes(remaining)
    requestAnimationFrame(() => {
      itemRefs.current[index + 1]?.focus()
    })
  }

  return (
    <ul className="flex flex-col gap-4" aria-label="Inspection notes">
      {notes.map((note, index) => (
        <NoteCard
          key={note.id}
          ref={(el) => (itemRefs.current[index] = el)}
          note={note}
          onDelete={() => handleDelete(index)}
        />
      ))}
    </ul>
  )
}

