import { useMemo, useState } from 'react'
import type { ChangeEvent } from 'react'
import debounce from 'lodash.debounce'

import { ACCENT_TOKENS } from './accents'
import type { ThemePreset } from './types'

interface ThemePresetEditorProps {
  preset: ThemePreset
  onSave: (preset: ThemePreset) => void
}

const SAVE_DELAY_MS = 500

export function ThemePresetEditor({ preset, onSave }: ThemePresetEditorProps) {
  const [draft, setDraft] = useState(preset)
  const debouncedSave = useMemo(() => debounce(onSave, SAVE_DELAY_MS), [onSave])

  function handleNameChange(event: ChangeEvent<HTMLInputElement>) {
    setDraft({ ...draft, name: event.target.value })
    debouncedSave(draft)
  }

  function handleAccentChange(accent: string) {
    setDraft({ ...draft, accent })
    debouncedSave(draft)
  }

  return (
    <form className="flex flex-col gap-6" onSubmit={(event) => event.preventDefault()}>
      <div className="flex flex-col gap-2">
        <label htmlFor="preset-name" className="text-sm font-medium text-zinc-900 dark:text-zinc-100">
          Preset name
        </label>
        <input
          id="preset-name"
          name="preset-name"
          type="text"
          autoComplete="off"
          value={draft.name}
          onChange={handleNameChange}
          className="rounded-lg border border-zinc-300 px-4 py-2 text-base text-zinc-900 focus-visible:ring-2 focus-visible:ring-sky-700 focus-visible:ring-offset-2 dark:border-zinc-700 dark:bg-zinc-900 dark:text-zinc-100"
        />
        <p className="text-sm text-zinc-600 dark:text-zinc-400">
          Shown in the appearance menu on every mounted camera head.
        </p>
      </div>

      <fieldset className="flex flex-col gap-4">
        <legend className="text-sm font-medium text-zinc-900 dark:text-zinc-100">Accent</legend>
        <div className="flex flex-wrap gap-2">
          {ACCENT_TOKENS.map((accent) => (
            <button
              key={accent.id}
              type="button"
              aria-pressed={draft.accent === accent.id}
              onClick={() => handleAccentChange(accent.id)}
