import { fireEvent, render, screen } from '@testing-library/react'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

import { ThemePresetEditor } from './ThemePresetEditor'

const preset = { id: 'preset-31', name: 'Night Dock', accent: 'sky' }

describe('ThemePresetEditor autosave', () => {
  beforeEach(() => {
    vi.useFakeTimers()
  })

  afterEach(() => {
    vi.useRealTimers()
  })

  it('saves the value from the last keystroke, not the one before it', () => {
    const onSave = vi.fn()
    render(<ThemePresetEditor preset={preset} onSave={onSave} />)
    const field = screen.getByLabelText('Preset name')

    fireEvent.change(field, { target: { value: 'Dock Ambe' } })
    fireEvent.change(field, { target: { value: 'Dock Amber' } })
    vi.advanceTimersByTime(600)

    expect(onSave).toHaveBeenCalledTimes(1)
    expect(onSave).toHaveBeenCalledWith(expect.objectContaining({ name: 'Dock Amber' }))
  })

  it('saves the accent that was just picked alongside the current name', () => {
    const onSave = vi.fn()
    render(<ThemePresetEditor preset={preset} onSave={onSave} />)

    fireEvent.change(screen.getByLabelText('Preset name'), { target: { value: 'Dock Amber' } })
    fireEvent.click(screen.getByRole('button', { name: 'Amber' }))
    vi.advanceTimersByTime(600)

    expect(onSave).toHaveBeenCalledWith(expect.objectContaining({ name: 'Dock Amber', accent: 'amber' }))
  })
})

