  const received = manifest.items.filter((item) => item.bytesReceived >= item.bytesExpected).length

  return (
    <dl className="grid grid-cols-1 gap-6 md:grid-cols-2">
      <div className="flex flex-col gap-2">
        <dt className="text-sm font-medium text-stone-600 dark:text-stone-400">Items received</dt>
