import { useEffect, useState } from 'react'

import { fetchTransferManifest, openManifestSocket } from './manifestClient'
import type { TransferManifest } from './types'

export function mergeManifest(current: TransferManifest | null, incoming: TransferManifest) {
  if (current !== null && current.observedAt >= incoming.observedAt) {
    return current
  }
  return incoming
}

export function useTransferManifest(accessionId: string) {
  const [manifest, setManifest] = useState<TransferManifest | null>(null)
  const [error, setError] = useState<Error | null>(null)

  useEffect(() => {
    let closed = false

    const socket = openManifestSocket(accessionId, (snapshot) => {
      if (closed) return
      setManifest((current) => mergeManifest(current, snapshot))
    })

    fetchTransferManifest(accessionId)
      .then((initial) => {
        if (closed) return
        setManifest((current) => mergeManifest(current, initial))
      })
      .catch((cause: unknown) => {
        if (closed) return
        setError(cause instanceof Error ? cause : new Error('The transfer manifest is unavailable'))
      })

    return () => {
      closed = true
      socket.close()
    }
  }, [accessionId])

  return { manifest, error }
}

import type { TransferItem, TransferManifest } from './types'

interface ManifestSummaryProps {
  manifest: TransferManifest | null
}

const STALLED_AFTER_MS = 10 * 60 * 1000
const megabytes = new Intl.NumberFormat('en-GB', { maximumFractionDigits: 1 })
const clockTime = new Intl.DateTimeFormat('en-GB', {
  hour: '2-digit',
  minute: '2-digit',
  timeZone: 'Europe/London',
})

export function isStalled(item: TransferItem, observedAt: string) {
  if (item.bytesReceived >= item.bytesExpected) return false
  return Date.parse(observedAt) - Date.parse(item.lastMovedAt) > STALLED_AFTER_MS
}

function inMegabytes(bytes: number) {
  return megabytes.format(bytes / 1_000_000)
}

export function ManifestSummary({ manifest }: ManifestSummaryProps) {
  if (manifest === null) {
    return <div className="h-64 rounded-md bg-stone-200 dark:bg-stone-800" aria-hidden="true" />
  }

  const received = manifest.items.filter((item) => item.bytesReceived >= item.bytesExpected).length
  const stalled = manifest.items.filter((item) => isStalled(item, manifest.observedAt)).length

  return (
    <section className="flex flex-col gap-6">
      <dl className="grid grid-cols-1 gap-6 md:grid-cols-3">
        <div className="flex flex-col gap-2">
          <dt className="text-sm font-medium text-stone-600 dark:text-stone-400">Items received</dt>
          <dd className="text-2xl font-semibold tabular-nums leading-tight text-stone-900 dark:text-stone-100">
            {received} of {manifest.items.length}
          </dd>
        </div>
        <div className="flex flex-col gap-2">
          <dt className="text-sm font-medium text-stone-600 dark:text-stone-400">Stalled over 10 minutes</dt>
          <dd className="text-2xl font-semibold tabular-nums leading-tight text-stone-900 dark:text-stone-100">
            {stalled}
          </dd>
        </div>
        <div className="flex flex-col gap-2">
          <dt className="text-sm font-medium text-stone-600 dark:text-stone-400">Manifest read at</dt>
          <dd className="text-2xl font-semibold tabular-nums leading-tight text-stone-900 dark:text-stone-100">
            {clockTime.format(new Date(manifest.observedAt))}
          </dd>
        </div>
      </dl>
      {manifest.items.length === 0 ? (
        <p className="text-base text-stone-700 dark:text-stone-300">
          The depositor has not started this transfer. Send them the deposit link again from the contacts step.
        </p>
      ) : (
        <table className="w-full border-collapse text-left">
          <caption className="sr-only">Deposit items in this transfer, with bytes received against bytes expected</caption>
          <thead>
            <tr className="border-b border-stone-200 dark:border-stone-800">
              <th scope="col" className="px-4 py-2 text-sm font-medium text-stone-600 dark:text-stone-400">Item</th>
              <th scope="col" className="px-4 py-2 text-sm font-medium text-stone-600 dark:text-stone-400">Progress</th>
              <th scope="col" className="px-4 py-2 text-right text-sm font-medium text-stone-600 dark:text-stone-400">Received (MB)</th>
            </tr>
          </thead>
          <tbody>
            {manifest.items.map((item) => (
              <tr key={item.id} className="border-b border-stone-100 dark:border-stone-900">
                <td className="px-4 py-3 text-base text-stone-900 dark:text-stone-100">
                  <span className="block min-w-0 truncate" title={item.label}>{item.label}</span>
                  {isStalled(item, manifest.observedAt) ? (
                    <span className="mt-2 flex items-center gap-2 text-sm text-amber-800 dark:text-amber-300">
                      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={1.5} className="size-4" aria-hidden="true">
                        <circle cx="12" cy="12" r="9" />
                        <path d="M12 7v5l3 2" strokeLinecap="round" />
                      </svg>
                      Stalled, no bytes for over 10 minutes
                    </span>
                  ) : null}
                </td>
                <td className="px-4 py-3">
                  <progress
                    value={item.bytesReceived}
                    max={item.bytesExpected}
                    aria-label={'Transfer progress for ' + item.label}
                    className="h-2 w-full"
                  />
                </td>
                <td className="px-4 py-3 text-right text-base tabular-nums text-stone-900 dark:text-stone-100">
                  {inMegabytes(item.bytesReceived)} of {inMegabytes(item.bytesExpected)}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </section>
  )
}

