import { hasScope } from '../auth/scopeClient'
import type { HandoverGate } from './types'

const REQUIRED_SCOPES = ['handover:approve', 'vehicle:release', 'damage:waive'] as const

export async function loadHandoverGate(memberId: string): Promise<HandoverGate> {
  const flags = await Promise.all(
    REQUIRED_SCOPES.map((scope) => ({ scope, granted: hasScope(memberId, scope) })),
  )

  const missing = flags.filter((entry) => !entry.granted).map((entry) => entry.scope)

  return {
    canApproveHandover: missing.length === 0,
    missingScopes: missing,
  }
}

