import { describe, expect, it, vi } from 'vitest'

import { hasScope } from '../auth/scopeClient'
import { loadHandoverGate } from './gate'

vi.mock('../auth/scopeClient', () => ({ hasScope: vi.fn() }))

function holding(scopes: string[]) {
  return (_memberId: string, scope: string) => Promise.resolve(scopes.includes(scope))
}

describe('loadHandoverGate', () => {
  it('keeps the handover closed and names what a valet is missing', async () => {
    vi.mocked(hasScope).mockImplementation(holding(['vehicle:release']))

    const gate = await loadHandoverGate('mem-70912')

    expect(gate.canApproveHandover).toBe(false)
    expect(gate.missingScopes).toEqual(['handover:approve', 'damage:waive'])
  })

  it('opens the handover for a delivery lead holding every scope', async () => {
    vi.mocked(hasScope).mockImplementation(holding(['handover:approve', 'vehicle:release', 'damage:waive']))

    const gate = await loadHandoverGate('mem-41338')

    expect(gate.canApproveHandover).toBe(true)
    expect(gate.missingScopes).toEqual([])
  })

  it('checks every required scope once', async () => {
    vi.mocked(hasScope).mockImplementation(holding([]))

    await loadHandoverGate('mem-41338')

    expect(hasScope).toHaveBeenCalledTimes(3)
  })
})

