export function matchDayLabel(nextFixtureAt: string, now: Date): string {
  const days = Math.round((Date.parse(nextFixtureAt) - now.getTime()) / 86400000)
  if (days < 0) {
    return Math.abs(days) + ' days ago'
  }
  return 'in ' + days + ' days'
}

export function OfficialsPanel({ officials, isLoading }: OfficialsPanelProps) {
  const now = new Date()

  return (
    <section className="mx-auto flex w-full max-w-7xl flex-col gap-6">
      <h2 className="text-xl font-semibold leading-tight text-slate-900 dark:text-slate-100">Officials on call</h2>
      {isLoading ? (
        <div role="status" aria-label="Loading officials" className="flex min-h-16 items-center justify-center">
          <span className="size-6 animate-spin rounded-full border-2 border-slate-300 border-t-slate-700 dark:border-slate-700 dark:border-t-slate-200" />
        </div>
      ) : (
        <ul className="flex flex-col gap-2">
          {officials.map((official) => (
            <li
              key={official.id}
              className="flex min-h-16 flex-col gap-1 rounded-md border border-slate-200 px-4 py-3 dark:border-slate-800"
            >
              <span className="text-base font-medium text-slate-900 dark:text-slate-100">{official.name}</span>
              <span className="text-sm leading-relaxed text-slate-600 dark:text-slate-400">
                Grade {official.grade} - next fixture {matchDayLabel(official.nextFixtureAt, now)}
              </span>
            </li>
          ))}
        </ul>
      )}
    </section>
  )
}

