import { renderHook, waitFor } from '@testing-library/react'
import { beforeEach, describe, expect, it, vi } from 'vitest'

import { apiGet } from '../shared/api'
import { useEffectiveDateOptions } from './useEffectiveDateOptions'

vi.mock('../shared/api', () => ({ apiGet: vi.fn() }))

const CARRIERS = ['car-8', 'car-12']
const OCTOBER = { from: '2026-10-01', to: '2026-10-31' }

describe('useEffectiveDateOptions', () => {
  beforeEach(() => {
    vi.mocked(apiGet).mockReset()
    vi.mocked(apiGet).mockResolvedValue([{ day: '2026-10-01', binderCount: 2 }])
  })

  it('requests the options once for a range', async () => {
    renderHook(() => useEffectiveDateOptions(OCTOBER, CARRIERS))
    await waitFor(() => expect(vi.mocked(apiGet)).toHaveBeenCalledTimes(1))
  })

  it('does not request again when the parent rebuilds an equal range object', async () => {
    const view = renderHook(({ from, to }) => useEffectiveDateOptions({ from, to }, CARRIERS), {
      initialProps: OCTOBER,
    })
    await waitFor(() => expect(vi.mocked(apiGet)).toHaveBeenCalledTimes(1))
    view.rerender({ from: '2026-10-01', to: '2026-10-31' })
    view.rerender({ from: '2026-10-01', to: '2026-10-31' })
    expect(vi.mocked(apiGet)).toHaveBeenCalledTimes(1)
  })

  it('does not request again when the parent rebuilds an equal carrier list', async () => {
    const view = renderHook(({ ids }) => useEffectiveDateOptions(OCTOBER, ids), {
      initialProps: { ids: ['car-8', 'car-12'] },
    })
    await waitFor(() => expect(vi.mocked(apiGet)).toHaveBeenCalledTimes(1))
    view.rerender({ ids: ['car-8', 'car-12'] })
    view.rerender({ ids: ['car-8', 'car-12'] })
    expect(vi.mocked(apiGet)).toHaveBeenCalledTimes(1)
  })
})

