import { act, renderHook } from '@testing-library/react'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

import { useNewCommentPill } from './useNewCommentPill'

let frames = new Map<number, FrameRequestCallback>()
let nextHandle = 1

function flushFrame() {
  const queued = [...frames.values()]
  frames.clear()
  for (const callback of queued) callback(0)
}

function makeFeed(scrollTop: number) {
  const node = document.createElement('div')
  Object.defineProperty(node, 'scrollTop', { value: scrollTop, writable: true })
  Object.defineProperty(node, 'scrollHeight', { value: 2400, writable: true })
  Object.defineProperty(node, 'clientHeight', { value: 600, writable: true })
  return node
}

beforeEach(() => {
  frames = new Map()
  nextHandle = 1
  vi.stubGlobal('requestAnimationFrame', (callback: FrameRequestCallback) => {
    const handle = nextHandle++
    frames.set(handle, callback)
    return handle
  })
  vi.stubGlobal('cancelAnimationFrame', (handle: number) => {
    frames.delete(handle)
  })
})

afterEach(() => {
  vi.unstubAllGlobals()
})

describe('useNewCommentPill', () => {
  it('follows the feed as it scrolls, not the offset it opened at', () => {
    const feed = makeFeed(1800)
    const { result } = renderHook(() => useNewCommentPill({ current: feed }))

    act(() => flushFrame())
    expect(result.current).toBe(false)

    feed.scrollTop = 400
    act(() => flushFrame())
    expect(result.current).toBe(true)
  })

  it('drops the pill once the reader is back at the newest comment', () => {
    const feed = makeFeed(400)
    const { result } = renderHook(() => useNewCommentPill({ current: feed }))

    act(() => flushFrame())
    expect(result.current).toBe(true)

    feed.scrollTop = 1800
    act(() => flushFrame())
    expect(result.current).toBe(false)
  })

  it('stops asking for frames when the feed unmounts', () => {
    const feed = makeFeed(400)
    const { unmount } = renderHook(() => useNewCommentPill({ current: feed }))

    act(() => flushFrame())
    unmount()

    expect(frames.size).toBe(0)
  })
})

