import { CloseIcon } from './icons'

interface ModalShellProps {
  title: string
  onClose: () => void
  children: ReactNode
}

export function ModalShell({ title, onClose, children }: ModalShellProps) {
  useEffect(() => {
    function onKeyDown(event: KeyboardEvent) {
      if (event.key === 'Escape') {
        onClose()
      }
