import type { ManifestPiece } from './types'

interface ManifestTableProps {
  pieces: ManifestPiece[]
  awbNumber: string
}

function pieceDetail(piece: ManifestPiece) {
  if (piece.kind === 'cargo') {
    const { l, w, h } = piece.dimsCm
    return l + ' x ' + w + ' x ' + h + ' cm'
  }
  return piece.pages + ' pages'
}

export function ManifestTable({ pieces, awbNumber }: ManifestTableProps) {
