import type { DeploymentShift, ShiftCell, ShiftTable } from './types'

export function shiftFor(shifts: ShiftTable, dayKey: string): DeploymentShift | undefined {
  return shifts[dayKey]
}

export function weekShiftSummary(shifts: ShiftTable, dayKeys: string[]): ShiftCell[] {
  return dayKeys.map((dayKey) => {
    const shift = shiftFor(shifts, dayKey)
    if (!shift) {
      return { dayKey, startsAt: null, crewSize: 0 }
    }
    return {
      dayKey,
      startsAt: shift.startsAt,
      crewSize: shift.crewSize,
    }
  })
}

export function totalCrewForWeek(shifts: ShiftTable, dayKeys: string[]) {
  return weekShiftSummary(shifts, dayKeys).reduce((sum, cell) => sum + cell.crewSize, 0)
}

import { describe, expect, it } from 'vitest'

import { totalCrewForWeek, weekShiftSummary } from './weekShifts'

const shifts = {
  '2026-07-06': { startsAt: '06:30', crewSize: 4 },
  '2026-07-09': { startsAt: '07:00', crewSize: 6 },
}

const week = ['2026-07-06', '2026-07-07', '2026-07-08', '2026-07-09', '2026-07-10']

describe('weekShiftSummary', () => {
  it('returns an empty cell for a day with no roster row', () => {
    expect(weekShiftSummary(shifts, week)[1]).toEqual({
      dayKey: '2026-07-07',
      startsAt: null,
      crewSize: 0,
    })
  })

  it('keeps the rostered days intact', () => {
    expect(weekShiftSummary(shifts, week)[0]).toEqual({
      dayKey: '2026-07-06',
      startsAt: '06:30',
      crewSize: 4,
    })
  })

  it('counts crew across a week with gaps', () => {
    expect(totalCrewForWeek(shifts, week)).toBe(10)
  })
})

