import type { DepthUnit, StationProfile } from './types'

const OVERRIDE_KEY = 'rainshadow.depthUnit'

function readOverride(): DepthUnit | null {
  const stored = window.localStorage.getItem(OVERRIDE_KEY)
  return stored === 'mm' || stored === 'in' ? stored : null
}

export function useDepthUnit(profile: StationProfile | null) {
  const [unit, setUnit] = useState<DepthUnit>(readOverride() ?? profile?.depthUnit ?? 'mm')

  const chooseUnit = (next: DepthUnit) => {
    window.localStorage.setItem(OVERRIDE_KEY, next)
    setUnit(next)
  }

  return { unit, chooseUnit }
}

