    const { result, rerender } = renderHook(({ profile }) => useDepthUnit(profile), {
      initialProps: { profile: null as typeof cabraVale | null },
    })
    act(() => {
      result.current.chooseUnit('mm')
    })
    rerender({ profile: cabraVale })
    expect(result.current.unit).toBe('mm')
