import { useState } from 'react'
import type { FormEvent } from 'react'

import { checkPermitFields } from '../../lib/permitRules'
import type { PermitDraft } from '../types'

interface PermitFormProps {
  draft: PermitDraft
  onSubmit: (draft: PermitDraft) => Promise<void>
}

export function PermitForm({ draft, onSubmit }: PermitFormProps) {
  const [values, setValues] = useState(draft)
  const [errors, setErrors] = useState<string[]>([])
  const [checking, setChecking] = useState(false)

  function runChecks(next: PermitDraft) {
    setChecking(true)
    window.setTimeout(() => {
      setErrors(checkPermitFields(next))
      setChecking(false)
    }, 400)
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    await onSubmit(values)
  }

  const disabled = checking || errors.length > 0

  return (
    <form onSubmit={handleSubmit} className="flex flex-col gap-6 pb-24 md:pb-0">
      <div className="flex flex-col gap-2">
        <label htmlFor="permit-acres" className="text-sm font-medium text-neutral-700 dark:text-neutral-300">
          Acres to burn
        </label>
        <input
          id="permit-acres"
          type="number"
          inputMode="decimal"
          value={values.acres}
          onChange={(event) => setValues({ ...values, acres: Number(event.target.value) })}
          onBlur={() => runChecks(values)}
          aria-invalid={errors.length > 0}
          aria-describedby={errors.length > 0 ? 'permit-errors' : undefined}
          className="rounded-lg border border-neutral-300 px-4 py-2 text-base text-neutral-900 focus-visible:ring-2 focus-visible:ring-orange-700 focus-visible:ring-offset-2 dark:border-neutral-700 dark:bg-neutral-900 dark:text-neutral-100"
        />
        {errors.length > 0 ? (
          <p id="permit-errors" role="alert" className="text-sm text-red-700 dark:text-red-400">
            {errors[0]}
          </p>
        ) : null}
      </div>
      <div className="fixed inset-x-0 bottom-0 border-t border-neutral-200 bg-white p-4 dark:border-neutral-800 dark:bg-neutral-950 md:static md:border-0 md:bg-transparent md:p-0">
        <button
          type="submit"
          disabled={disabled}
          className="min-h-11 w-full rounded-lg bg-orange-700 px-4 py-2 text-base font-medium text-white hover:bg-orange-800 focus-visible:ring-2 focus-visible:ring-orange-700 focus-visible:ring-offset-2 active:scale-[0.98] disabled:pointer-events-none disabled:opacity-50 md:w-auto"
        >
          Submit burn permit
        </button>
      </div>
    </form>
  )
}

