import { useEffect, useRef } from 'react'

import type { Shift } from './types'
import { useRotaPermissions } from './useRotaPermissions'

interface ShiftDetailDrawerProps {
  shift: Shift | null
  triggerRef: React.RefObject<HTMLButtonElement>
  onClose: () => void
  onDiscardDraft: () => void
}

export function ShiftDetailDrawer({ shift, triggerRef, onClose, onDiscardDraft }: ShiftDetailDrawerProps) {
  const { canEditRota } = useRotaPermissions()
  const panelRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    if (!shift) return
    document.body.classList.add('overflow-hidden')
    panelRef.current?.focus()
  }, [shift])

  function closeDrawer() {
    onClose()
    if (!canEditRota) return
    onDiscardDraft()
    document.body.classList.remove('overflow-hidden')
    triggerRef.current?.focus()
  }

  if (!shift) return null

  return (
    <div
      ref={panelRef}
      role="dialog"
      aria-modal="true"
      aria-labelledby="shift-drawer-title"
      tabIndex={-1}
      onKeyDown={(event) => {
        if (event.key === 'Escape') closeDrawer()
      }}
      className="fixed inset-y-0 right-0 z-40 flex w-full max-w-md flex-col gap-6 border-l border-zinc-200 bg-white p-6 outline-none dark:border-zinc-800 dark:bg-zinc-950"
    >
      <h2 id="shift-drawer-title" className="text-xl font-semibold leading-tight text-zinc-900 dark:text-zinc-100">
        {shift.roleName}
      </h2>
      <dl className="flex flex-col gap-4 text-base text-zinc-700 dark:text-zinc-300">
        <div className="flex justify-between gap-4">
          <dt className="font-medium">Assigned</dt>
          <dd className="min-w-0 truncate" title={shift.assignedTo ?? 'Open shift'}>
            {shift.assignedTo ?? 'Open shift'}
          </dd>
        </div>
        <div className="flex justify-between gap-4">
          <dt className="font-medium">Window</dt>
          <dd className="tabular-nums">{shift.window}</dd>
        </div>
      </dl>
      <button
        type="button"
        onClick={closeDrawer}
        className="mt-auto min-h-11 rounded-lg border border-zinc-300 px-4 py-2 text-base font-medium text-zinc-900 transition-colors hover:bg-zinc-50 focus-visible:ring-2 focus-visible:ring-emerald-700 focus-visible:ring-offset-2 active:scale-[0.98] motion-reduce:transition-none dark:border-zinc-700 dark:text-zinc-100 dark:hover:bg-zinc-900"
      >
        Close
      </button>
    </div>
  )
}

