import { render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { useRef, useState } from 'react'
import { describe, expect, it, vi } from 'vitest'

import { ShiftDetailDrawer } from './ShiftDetailDrawer'

vi.mock('./useRotaPermissions', () => ({
  useRotaPermissions: () => ({ canEditRota: false }),
}))

const shift = {
  id: 'sh-4471',
  roleName: 'Nights picker, Bay 3',
  assignedTo: 'Priya Raman',
  window: '22:00 - 06:30',
}

function Harness() {
  const triggerRef = useRef<HTMLButtonElement>(null)
  const [open, setOpen] = useState(false)
  return (
    <div>
      <button type="button" ref={triggerRef} onClick={() => setOpen(true)}>
        Nights picker, Bay 3
      </button>
      <ShiftDetailDrawer
        shift={open ? shift : null}
        triggerRef={triggerRef}
        onClose={() => setOpen(false)}
        onDiscardDraft={vi.fn()}
      />
    </div>
  )
}

describe('ShiftDetailDrawer', () => {
  it('unlocks page scroll when a viewer closes with Escape', async () => {
    const user = userEvent.setup()
    render(<Harness />)
    await user.click(screen.getByRole('button', { name: 'Nights picker, Bay 3' }))
    expect(document.body.classList.contains('overflow-hidden')).toBe(true)
    await user.keyboard('{Escape}')
    expect(document.body.classList.contains('overflow-hidden')).toBe(false)
  })

  it('returns focus to the shift tile after Escape', async () => {
    const user = userEvent.setup()
    render(<Harness />)
    const trigger = screen.getByRole('button', { name: 'Nights picker, Bay 3' })
    await user.click(trigger)
    await user.keyboard('{Escape}')
    expect(trigger).toHaveFocus()
  })
})

