const TELEMETRY_URL = '/api/telemetry/shortcut'

interface ShortcutEvent {
  name: string
  targetId: string
  at: string
}

async function postTelemetry(event: ShortcutEvent) {
  const response = await fetch(TELEMETRY_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(event),
  })
  if (!response.ok) {
    throw new Error(`POST ${TELEMETRY_URL} ${response.status} ${response.statusText}`)
  }
}

export function trackShortcut(name: string, targetId: string) {
  return postTelemetry({ name, targetId, at: new Date().toISOString() })
}

