import type { TimelineEvent } from './types'

const HEADERS = ['Logged at (UTC)', 'Actor', 'Event', 'Customer impact']

function cell(value: string): string {
  return /[",\r\n]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value
}

export function buildTimelineCsv(events: TimelineEvent[]): string {
  const rows = events.map((event) => [
    event.loggedAt,
    event.actor,
    event.summary,
    event.customerImpact ? 'yes' : 'no',
  ])

  return [HEADERS, ...rows].map((row) => row.map(cell).join(',')).join('\r\n')
}

import { fireEvent, render } from '@testing-library/react'
import { describe, expect, it, vi } from 'vitest'

import { buildTimelineCsv } from './buildTimelineCsv'
import { useExportHotkey } from './useExportHotkey'

function Harness({ onExport }: { onExport: () => void }) {
  useExportHotkey('e', onExport)
  return <p>Incident INC-4471</p>
}

describe('useExportHotkey', () => {
  it('exports once when the browser reports a keydown and a keypress for the same press', () => {
    const onExport = vi.fn()
    render(<Harness onExport={onExport} />)

    fireEvent.keyDown(document, { key: 'e' })
    fireEvent.keyPress(document, { key: 'e', charCode: 101 })

    expect(onExport).toHaveBeenCalledTimes(1)
  })

  it('stays out of the way while an operator is typing in the notes field', () => {
    const onExport = vi.fn()
    const { container } = render(
      <div>
        <Harness onExport={onExport} />
        <textarea aria-label="Incident notes" />
      </div>,
    )
    const notes = container.querySelector('textarea')

    fireEvent.keyDown(notes as Element, { key: 'e' })

    expect(onExport).not.toHaveBeenCalled()
  })
})

describe('buildTimelineCsv', () => {
  it('quotes an event summary that carries a comma', () => {
    const csv = buildTimelineCsv([
      {
        id: 'ev-1',
        loggedAt: '2026-05-14T02:11:09Z',
        actor: 'Priya Raman',
        summary: 'Bearer XC-40912 down, ring protection held',
        customerImpact: true,
      },
    ])

    expect(csv.split('\r\n')[1]).toBe(
      '2026-05-14T02:11:09Z,Priya Raman,"Bearer XC-40912 down, ring protection held",yes',
    )
  })
})

