import { render, screen } from '@testing-library/react'
import { afterEach, describe, expect, it, vi } from 'vitest'

import { Popover } from './Popover'

afterEach(() => {
  document.getElementById('theme-root')?.remove()
})

function mountThemeRoot() {
  const root = document.createElement('div')
  root.id = 'theme-root'
  root.className = 'theme-verge'
  document.body.append(root)
  return root
}

describe('Popover', () => {
  it('renders inside the theme root so the surface tokens resolve', () => {
    const root = mountThemeRoot()
    render(
      <Popover label="Edit sweep window" onClose={vi.fn()}>
        <p>Milton Road, 05:30 to 07:00</p>
      </Popover>,
    )

    const card = screen.getByRole('dialog', { name: 'Edit sweep window' })
    expect(root.contains(card)).toBe(true)
  })

  it('falls back to the body when no theme root is mounted', () => {
    render(
      <Popover label="Edit sweep window" onClose={vi.fn()}>
        <p>Milton Road, 05:30 to 07:00</p>
      </Popover>,
    )

    const card = screen.getByRole('dialog', { name: 'Edit sweep window' })
    expect(card.parentElement).toBe(document.body)
  })
})

