export type DueTone = 'overdue' | 'today' | 'upcoming'

export interface DueChip {
  text: string
  detail: string
  tone: DueTone
}

// dueOn is the plain calendar date the cruiser picked in the field, e.g. '2026-03-14'.
export function dueLabel(dueOn: string, now: Date): DueChip {
  const today = now.toISOString().slice(0, 10)
  const detail = new Date(dueOn).toLocaleDateString('en-CA', { month: 'short', day: 'numeric' })

  if (dueOn === today) {
    return { text: 'Due today', detail, tone: 'today' }
  }
  if (dueOn < today) {
    return { text: 'Overdue', detail, tone: 'overdue' }
  }
  return { text: 'Due later', detail, tone: 'upcoming' }
}

