import { useEffect, useId, useRef } from 'react'
import { createPortal } from 'react-dom'

interface RetryDialogProps {
  title: string
  detail: string
  onRetry: () => void
  onClose: () => void
}

export function RetryDialog({ title, detail, onRetry, onClose }: RetryDialogProps) {
  const headingId = useId()
  const closeRef = useRef<HTMLButtonElement>(null)

  useEffect(() => {
    closeRef.current?.focus()
    function onKeyDown(event: KeyboardEvent) {
      if (event.key === 'Escape') {
        onClose()
      }
    }
    document.addEventListener('keydown', onKeyDown)
    return () => {
      document.removeEventListener('keydown', onKeyDown)
    }
  }, [onClose])

  return createPortal(
    <div className="fixed inset-0 z-40 flex items-center justify-center bg-zinc-950/40 px-4">
      <div
        role="dialog"
        aria-modal="true"
        aria-labelledby={headingId}
        className="flex w-full max-w-md flex-col gap-6 rounded-md bg-white p-6 shadow-lg dark:bg-zinc-900"
      >
        <h2 id={headingId} className="text-xl font-semibold leading-tight text-zinc-900 dark:text-zinc-100">
          {title}
        </h2>
        <p className="text-base leading-relaxed text-zinc-700 dark:text-zinc-300">{detail}</p>
        <div className="flex justify-end gap-4">
          <button
            ref={closeRef}
            type="button"
            onClick={onClose}
            className="min-h-11 rounded-md border border-zinc-300 px-4 text-base font-medium text-zinc-900 hover:bg-zinc-100 focus-visible:ring-2 focus-visible:ring-zinc-700 focus-visible:ring-offset-2 active:scale-[0.98] dark:border-zinc-700 dark:text-zinc-100 dark:hover:bg-zinc-800"
          >
            Close
          </button>
          <button
            type="button"
            onClick={onRetry}
            className="min-h-11 rounded-md bg-red-700 px-4 text-base font-medium text-white hover:bg-red-800 focus-visible:ring-2 focus-visible:ring-red-700 focus-visible:ring-offset-2 active:scale-[0.98] disabled:pointer-events-none disabled:opacity-50 dark:bg-red-600 dark:hover:bg-red-500"
          >
            Send it again
          </button>
        </div>
      </div>
    </div>,
    document.body,
  )
}

