export function IncidentList({ incidents, isLoading }: IncidentListProps) {
  const [selectedId, setSelectedId] = useState<string | null>(null)

  const failed = incidents.filter((incident) => incident.syncState === 'failed')

  const handleRetry = useCallback(() => {
    if (selectedId) {
      void retryIncidentSync(selectedId)
    }
  }, [])

  if (isLoading) {
    return (
      <ul aria-busy="true" aria-label="Loading incidents" className="flex flex-col gap-2">
        {[0, 1, 2, 3].map((slot) => (
          <li
            key={slot}
            className="h-16 animate-pulse rounded-md bg-zinc-100 motion-reduce:animate-none dark:bg-zinc-900"
          />
        ))}
      </ul>
    )
  }

  return (
    <section className="flex flex-col gap-6">
      {failed.length > 0 ? (
        <div
          role="alert"
          className="flex flex-col gap-4 rounded-md border border-red-300 px-4 py-3 dark:border-red-900"
        >
          <p className="text-base leading-relaxed text-zinc-900 dark:text-zinc-100">
            {failed.length} incidents have not reached control. Stewards on those stands have not been told.
          </p>
          <button
            type="button"
            onClick={() => setSelectedId(failed[0].id)}
            className="min-h-11 self-start rounded-md bg-red-700 px-4 text-base font-medium text-white hover:bg-red-800 focus-visible:ring-2 focus-visible:ring-red-700 focus-visible:ring-offset-2 active:scale-[0.98] disabled:pointer-events-none disabled:opacity-50 dark:bg-red-600 dark:hover:bg-red-500"
          >
            Look at the first one
          </button>
        </div>
      ) : null}
      <ul className="flex flex-col gap-2">
        {incidents.map((incident) => (
          <li
            key={incident.id}
            className="flex min-h-16 items-center gap-4 rounded-md border border-zinc-200 px-4 py-3 dark:border-zinc-800"
          >
            <span className="min-w-0 flex-1 truncate text-base text-zinc-900 dark:text-zinc-100" title={incident.summary}>
              {incident.summary}
            </span>
            <span className="text-sm text-zinc-600 dark:text-zinc-400">{incident.stand}</span>
          </li>
        ))}
      </ul>
      {selectedId ? (
        <RetryDialog
          title="An incident did not reach control"
          detail="Control has not acknowledged this incident."
          onRetry={handleRetry}
          onClose={() => setSelectedId(null)}
        />
      ) : null}
    </section>
  )
}

