import { fireEvent, render, screen } from '@testing-library/react'
import { describe, expect, it, vi } from 'vitest'

import { IncidentList } from './IncidentList'
import { retryIncidentSync } from './incidentsApi'

vi.mock('./incidentsApi', () => ({
  retryIncidentSync: vi.fn(() => Promise.resolve()),
}))

const incidents = [
  {
    id: 'in-4412',
    stand: 'North stand',
    summary: 'Barrier 12 pushed forward at kickoff',
    syncState: 'failed',
    lastError: 'Control desk refused the packet, code 409',
  },
  {
    id: 'in-4419',
    stand: 'East stand',
    summary: 'Smoke device in row F',
    syncState: 'failed',
    lastError: 'Timed out after 30 seconds',
  },
  {
    id: 'in-4421',
    stand: 'East stand',
    summary: 'Medical call row B',
    syncState: 'sent',
    lastError: null,
  },
]

describe('IncidentList', () => {
  it('retries the incident whose own row opened the dialog', () => {
    render(<IncidentList incidents={incidents} isLoading={false} />)

    fireEvent.click(screen.getByRole('button', { name: 'Why incident in-4419 failed' }))
    const dialog = screen.getByRole('dialog', { name: 'Incident in-4419 did not reach control' })
    expect(dialog).toBeInTheDocument()
    expect(screen.getByText('Timed out after 30 seconds')).toBeInTheDocument()

    fireEvent.click(screen.getByRole('button', { name: 'Send it again' }))
    expect(retryIncidentSync).toHaveBeenCalledWith('in-4419')
  })
})

