import { useEffect, useState } from 'react'

import { setShortcutBusy } from '../../shortcuts/shortcutBusy'
import { saveScorecard } from './api'
import type { Scorecard } from './types'

interface FeedbackDialogProps {
  candidateId: string
  scorecard: Scorecard
  onSaved: () => void
  onCancel: () => void
}

export function FeedbackDialog({ candidateId, scorecard, onSaved, onCancel }: FeedbackDialogProps) {
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    setShortcutBusy(saving)
  }, [saving])

  async function submitFeedback() {
    setSaving(true)
    setError(null)
    try {
      await saveScorecard(candidateId, scorecard)
      onSaved()
    } catch {
      setError('Scorecard did not save. Check your connection and press Cmd+Enter again.')
    } finally {
      setSaving(false)
    }
  }

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-label="Interview scorecard"
      onKeyDown={(event) => {
        if (event.key === 'Enter' && event.metaKey) void submitFeedback()
        if (event.key === 'Escape' && !saving) onCancel()
      }}
      className="flex w-full max-w-lg flex-col gap-6 rounded-lg border border-zinc-200 bg-white p-6 dark:border-zinc-800 dark:bg-zinc-950"
    >
      <h2 className="text-xl font-semibold leading-tight text-zinc-900 dark:text-zinc-100">
        Scorecard for {scorecard.candidateName}
      </h2>
      {error ? (
        <p role="alert" className="text-base text-rose-700 dark:text-rose-400">
          {error}
        </p>
      ) : null}
      <button
        type="button"
        disabled={saving}
        onClick={() => void submitFeedback()}
        className="min-h-11 rounded-lg bg-indigo-700 px-4 py-2 text-base font-medium text-white transition-colors hover:bg-indigo-800 focus-visible:ring-2 focus-visible:ring-indigo-600 focus-visible:ring-offset-2 active:scale-[0.98] disabled:pointer-events-none disabled:opacity-50 motion-reduce:transition-none dark:bg-indigo-600 dark:hover:bg-indigo-500"
      >
        {saving ? 'Saving feedback' : 'Save scorecard'}
      </button>
    </div>
  )
}

