let busy = false
const listeners = new Set<() => void>()

export function setShortcutBusy(next: boolean) {
  if (busy === next) return
  busy = next
  listeners.forEach((listener) => listener())
}

export function isShortcutBusy() {
  return busy
}

export function subscribeShortcutBusy(listener: () => void) {
  listeners.add(listener)
  return () => {
    listeners.delete(listener)
  }
}

