import { useCallback, useEffect, useState } from 'react'
import { fetchHiveReadings, type HiveReading } from '../lib/telemetryApi'

interface HiveReadingsState {
  readings: HiveReading[]
  loading: boolean
  error: string | null
  refresh: () => void
}

export function useHiveReadings(hiveId: string): HiveReadingsState {
  const [readings, setReadings] = useState<HiveReading[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  const refresh = useCallback(() => {
    fetchHiveReadings(hiveId)
      .then((data) => {
        setReadings(data)
        setError(null)
      })
      .catch(() => setError('Readings for this hive are unavailable right now'))
  }, [hiveId])

  useEffect(() => {
    setLoading(true)
    fetchHiveReadings(hiveId)
      .then((data) => {
        setReadings(data)
        setError(null)
      })
      .catch(() => setError('Readings for this hive are unavailable right now'))
      .finally(() => setLoading(false))
  }, [hiveId])

  return { readings, loading, error, refresh }
}

