import { useEffect, useRef } from 'react'

import type { SetpointChange } from '../setpoints/types'
import { useSetpointHistory } from './useSetpointHistory'

interface SetpointHistoryRailProps {
  circuitId: string
}

const APPLIED_AT = new Intl.DateTimeFormat('en-CA', {
  hour: '2-digit',
  minute: '2-digit',
  hour12: false,
  timeZone: 'America/Santiago',
})

function describeChange(change: SetpointChange) {
  return change.label + ' ' + change.from + ' to ' + change.to + ' ' + change.unit
}

export function SetpointHistoryRail({ circuitId }: SetpointHistoryRailProps) {
  const { changes, cursor, stepBack } = useSetpointHistory(circuitId)
  const appliedRef = useRef<HTMLLIElement>(null)

  useEffect(() => {
    appliedRef.current?.scrollIntoView({ block: 'nearest' })
  }, [appliedRef])

  return (
    <aside className="flex h-full flex-col gap-6 border-l border-zinc-200 p-4 dark:border-zinc-800">
      <div className="flex items-center justify-between gap-6">
        <h2 className="text-base font-semibold text-zinc-900 dark:text-zinc-100">Setpoint history</h2>
        <button
          type="button"
          onClick={stepBack}
          disabled={cursor >= changes.length - 1}
          className="rounded-md border border-zinc-300 px-4 py-2 text-sm font-medium text-zinc-900 hover:bg-zinc-100 focus-visible:ring-2 focus-visible:ring-teal-700 focus-visible:ring-offset-2 active:scale-[0.98] disabled:opacity-50 disabled:pointer-events-none dark:border-zinc-700 dark:text-zinc-100 dark:hover:bg-zinc-900"
        >
          Step back
        </button>
      </div>
      <ul className="flex flex-col gap-2 overflow-y-auto">
        {changes.map((change, index) => (
          <li
            key={change.id}
            ref={index === cursor ? appliedRef : null}
            className={
              'flex flex-col gap-2 rounded-md px-4 py-2 ' +
              (index === cursor ? 'bg-teal-50 dark:bg-teal-950' : '')
            }
          >
            <span className="text-base text-zinc-900 dark:text-zinc-100">{describeChange(change)}</span>
            <span className="text-sm text-zinc-600 dark:text-zinc-400">
              {change.appliedBy},{' '}
              <span className="tabular-nums">{APPLIED_AT.format(new Date(change.appliedAt))}</span>
            </span>
          </li>
        ))}
      </ul>
    </aside>
  )
}

