import type { CachedReading } from '../features/gauges/types'

const READINGS_KEY = 'hydronet.readings'
const VERSION_KEY = 'hydronet.readings.version'

export const CACHE_VERSION = 3

export function isStaleCache(storedVersion: string | number | null): boolean {
  if (storedVersion === null) {
    return true
  }
  return storedVersion !== CACHE_VERSION
}

export function readCachedReadings(): CachedReading[] {
  const storedVersion = window.localStorage.getItem(VERSION_KEY)

  if (isStaleCache(storedVersion)) {
    window.localStorage.removeItem(READINGS_KEY)
