import { fireEvent, render, screen } from '@testing-library/react'
import { describe, expect, it, vi } from 'vitest'

import { RoutingPrefsPanel } from './RoutingPrefsPanel'

const savedPrefs = { channel: 'pager' as const, quietHours: true, escalateAfterMinutes: 15 }

describe('RoutingPrefsPanel', () => {
  it('saves the current draft when the operator presses Ctrl+S', () => {
    const onPersist = vi.fn().mockResolvedValue(undefined)
    render(<RoutingPrefsPanel savedPrefs={savedPrefs} onPersist={onPersist} />)

    fireEvent.change(screen.getByLabelText('Send alerts to'), { target: { value: 'shift-phone' } })
    fireEvent.keyDown(document, { key: 's', ctrlKey: true })

    expect(onPersist).toHaveBeenCalledTimes(1)
    expect(onPersist).toHaveBeenCalledWith({ ...savedPrefs, channel: 'shift-phone' })
  })

  it('saves a second change made after the first save', () => {
    const onPersist = vi.fn().mockResolvedValue(undefined)
    render(<RoutingPrefsPanel savedPrefs={savedPrefs} onPersist={onPersist} />)

    fireEvent.change(screen.getByLabelText('Send alerts to'), { target: { value: 'shift-phone' } })
    fireEvent.keyDown(document, { key: 's', ctrlKey: true })
    fireEvent.change(screen.getByLabelText('Send alerts to'), { target: { value: 'ops-room' } })
    fireEvent.keyDown(document, { key: 's', ctrlKey: true })

    expect(onPersist).toHaveBeenCalledTimes(2)
    expect(onPersist).toHaveBeenLastCalledWith({ ...savedPrefs, channel: 'ops-room' })
  })

  it('does nothing when Ctrl+S is pressed with no changes', () => {
    const onPersist = vi.fn().mockResolvedValue(undefined)
    render(<RoutingPrefsPanel savedPrefs={savedPrefs} onPersist={onPersist} />)

    fireEvent.keyDown(document, { key: 's', ctrlKey: true })

    expect(onPersist).not.toHaveBeenCalled()
  })
})

