const [declined, setDeclined] = useState(false)

async function handleRefund() {
  if (pending) return
  const optimistic: RefundRow = {
    id: 'pending-' + charge.id,
    chargeId: charge.id,
    amountCents,
    status: 'refunded',
  }
  setPending(true)
  setDeclined(false)
  onRefundRow(optimistic)
