import { render, screen, waitFor } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { describe, expect, it, vi } from 'vitest'

import { issueRefund } from '../api/refunds'
import { RefundActions } from './RefundActions'
import type { Charge } from '../types/refund'

vi.mock('../api/refunds', () => ({ issueRefund: vi.fn() }))

const charge: Charge = {
  id: 'ch_88214',
  merchantName: 'Rivera Hardware',
  refundableCents: 4250,
}

describe('RefundActions', () => {
  it('rolls the optimistic row back when the gateway declines', async () => {
    vi.mocked(issueRefund).mockRejectedValueOnce(new Error('refund declined with status 402'))
    const onRollback = vi.fn()
    render(<RefundActions charge={charge} onRefundRow={vi.fn()} onRollback={onRollback} />)

    await userEvent.click(screen.getByRole('button', { name: 'Refund' }))

    await waitFor(() => expect(onRollback).toHaveBeenCalledWith('pending-ch_88214'))
    expect(screen.getByRole('alert')).toHaveTextContent('declined this refund')
  })

  it('keeps Refund disabled until the gateway answers', async () => {
    let settle: (row: unknown) => void = () => {}
    vi.mocked(issueRefund).mockReturnValueOnce(
      new Promise((resolve) => {
        settle = resolve
      }),
    )
    render(<RefundActions charge={charge} onRefundRow={vi.fn()} onRollback={vi.fn()} />)

    const button = screen.getByRole('button', { name: 'Refund' })
    await userEvent.click(button)
    expect(button).toBeDisabled()

    settle({ id: 'rfn_5512', chargeId: charge.id, amountCents: 4250, status: 'refunded' })
    await waitFor(() => expect(button).toBeEnabled())
  })
})

