import { render, screen } from '@testing-library/react'
import { describe, expect, it, vi } from 'vitest'

import { ScopedActionButton } from './ScopedActionButton'

function renderButton(className?: string) {
  render(
    <ScopedActionButton
      requiredScope="pricing:override"
      scopes={['pricing:override']}
      deniedMessage="Price overrides are handled by the fitting supervisor on duty."
      onClick={vi.fn()}
      className={className}
    >
      Override quoted price
    </ScopedActionButton>,
  )
  return screen.getByRole('button', { name: 'Override quoted price' })
}

describe('ScopedActionButton', () => {
  it('keeps the base classes when the caller passes none', () => {
    const button = renderButton()
    expect(button.className).toContain('w-auto')
    expect(button.className).toContain('text-base')
  })

  it('lets the caller override the base width and text size', () => {
    const button = renderButton('w-full text-sm')
    expect(button.className).toContain('w-full')
    expect(button.className).toContain('text-sm')
    expect(button.className).not.toContain('w-auto')
    expect(button.className).not.toContain('text-base')
  })

  it('shows the denial copy instead of the control without the scope', () => {
    render(
      <ScopedActionButton
        requiredScope="pricing:override"
        scopes={['fitment:view']}
        deniedMessage="Price overrides are handled by the fitting supervisor on duty."
        onClick={vi.fn()}
      >
        Override quoted price
      </ScopedActionButton>,
    )
    expect(screen.queryByRole('button')).toBeNull()
    expect(screen.getByText('Price overrides are handled by the fitting supervisor on duty.')).toBeInTheDocument()
  })
})

