import { WEEKDAY_LABELS } from '../i18n/weekdays'

const WEEKDAY_KEYS = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'] as const

export function formatDepartureDay(iso: string, locale: string): string {
  const date = new Date(iso)
  const day = new Intl.DateTimeFormat(locale, {
    day: 'numeric',
    month: 'short',
  }).format(date)
  const key = WEEKDAY_KEYS[date.getDay() - 1]

  return WEEKDAY_LABELS[locale][key] + ' ' + day
}

