import { WEEKDAY_KEYS, WEEKDAY_LABELS } from '../../i18n/weekdays'

interface WeekPickerProps {
  locale: string
  selected: string
  onSelect: (key: string) => void
}

export function WeekPicker({ locale, selected, onSelect }: WeekPickerProps) {
  return (
    <div className="flex gap-2" role="group" aria-label="Day of week">
      {WEEKDAY_KEYS.map((key) => (
        <button
          key={key}
          type="button"
