export interface ParcelFilters {
  status: string
  owner: string
  minAcres: number
}

export const DEFAULT_PARCEL_FILTERS: ParcelFilters = { status: 'all', owner: '', minAcres: 0 }

export function parseParcelParams(params: URLSearchParams): ParcelFilters {
  const owner = params.get('owner') ?? DEFAULT_PARCEL_FILTERS.owner
  const minAcres = Number(params.get('minAcres') ?? DEFAULT_PARCEL_FILTERS.minAcres)
  const status = params.get('status') ?? DEFAULT_PARCEL_FILTERS.status

  return { owner, minAcres, status }
}

