import { useEffect, useState } from 'react'

import { fetchMutedStationPage } from './mutedStationsApi'
import type { MutedStation } from './types'

interface MutedStationsPanelProps {
  onUnmute: (stationId: string) => void
}

export function MutedStationsPanel({ onUnmute }: MutedStationsPanelProps) {
  const [rows, setRows] = useState<MutedStation[]>([])
  const [page, setPage] = useState(0)
  const [hasMore, setHasMore] = useState(true)
  const [status, setStatus] = useState<'idle' | 'loading' | 'error'>('idle')

  async function loadNextPage() {
    setStatus('loading')
    try {
      const result = await fetchMutedStationPage({ page: page + 1, query: '' })
      setRows((current) => [...current, ...result.rows])
      setPage(page + 1)
      setHasMore(result.hasMore)
      setStatus('idle')
    } catch {
      setStatus('error')
    }
  }

  useEffect(() => {
    void loadNextPage()
    // eslint-disable-next-line react-hooks/exhaustive-deps -- first page only, on mount
  }, [])

  return (
    <section className="flex flex-col gap-6">
      <div className="flex flex-col gap-2">
        <h2 className="text-2xl font-semibold leading-tight text-slate-900 dark:text-slate-100">Muted stations</h2>
        <p className="max-w-[65ch] text-base leading-relaxed text-slate-600 dark:text-slate-400">
          Passes over these stations stay off your alert feed until the mute expires.
        </p>
      </div>

      {rows.length === 0 && status === 'idle' ? (
        <p className="text-base leading-relaxed text-slate-600 dark:text-slate-400">
          Nothing is muted. Mute a station from any pass row to keep it off this feed.
        </p>
      ) : (
        <ul className="flex flex-col gap-2">
          {rows.map((station) => (
            <li
              key={station.stationId}
              className="flex items-center justify-between gap-4 border-b border-slate-200 py-2 dark:border-slate-800"
            >
              <span className="min-w-0 truncate text-base text-slate-900 dark:text-slate-100" title={station.name}>
                {station.name}
              </span>
              <span className="text-sm tabular-nums text-slate-600 dark:text-slate-400">
                until {station.mutedUntil.slice(0, 10)}
              </span>
              <button
                type="button"
                onClick={() => onUnmute(station.stationId)}
                className="rounded-md border border-slate-300 px-4 py-2 text-sm font-medium text-slate-700 hover:bg-slate-100 focus-visible:ring-2 focus-visible:ring-sky-700 focus-visible:ring-offset-2 dark:border-slate-700 dark:text-slate-300 dark:hover:bg-slate-900"
              >
                Unmute
              </button>
            </li>
          ))}
        </ul>
      )}

      {status === 'error' ? (
        <p role="alert" className="flex items-center gap-4 text-base text-red-700 dark:text-red-400">
          The muted station list did not load.
          <button
            type="button"
            onClick={() => void loadNextPage()}
            className="rounded-md border border-red-300 px-4 py-2 text-sm font-medium hover:bg-red-50 focus-visible:ring-2 focus-visible:ring-red-700 focus-visible:ring-offset-2 dark:border-red-800 dark:hover:bg-red-950"
          >
            Try again
          </button>
        </p>
      ) : null}

      {hasMore ? (
        <button
          type="button"
          disabled={status === 'loading'}
          onClick={() => void loadNextPage()}
          className="self-start rounded-md bg-sky-700 px-4 py-2 text-base font-medium text-white hover:bg-sky-800 focus-visible:ring-2 focus-visible:ring-sky-700 focus-visible:ring-offset-2 active:scale-[0.98] disabled:pointer-events-none disabled:opacity-50 dark:bg-sky-600 dark:hover:bg-sky-500"
        >
          {status === 'loading' ? 'Loading' : 'Load more'}
        </button>
      ) : null}
    </section>
  )
}

