export function useSubstationSearch(query: string) {
  const [results, setResults] = useState<Substation[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState('')

  useEffect(() => {
    if (query.trim().length < 2) {
      setResults([])
      return
    }
    setIsLoading(true)
    searchSubstations(query)
      .then((found) => {
        setResults(found)
        setIsLoading(false)
      })
      .catch(() => {
