import { useEffect, useState } from 'react'

import { searchSubstations } from './api'
import type { Substation } from './types'

export function useSubstationSearch(query: string) {
  const [results, setResults] = useState<Substation[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState('')

  useEffect(() => {
    if (query.trim().length < 2) {
      setResults([])
      setError('')
      return
    }

    const controller = new AbortController()
    setIsLoading(true)
    setError('')

    searchSubstations(query, controller.signal)
      .then((found) => {
        if (controller.signal.aborted) return
        setResults(found)
        setIsLoading(false)
      })
      .catch((cause) => {
        if (controller.signal.aborted) return
        setError(cause instanceof Error ? cause.message : 'Substation lookup is not responding.')
        setIsLoading(false)
      })

    return () => controller.abort()
  }, [query])

  return { results, isLoading, error }
}

import { render, screen, waitFor } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { beforeEach, describe, expect, it, vi } from 'vitest'

import { searchSubstations } from './api'
import { SubstationTypeahead } from './SubstationTypeahead'
import type { Substation } from './types'

vi.mock('./api', () => ({ searchSubstations: vi.fn() }))

const mocked = vi.mocked(searchSubstations)

function substation(code: string, name: string): Substation {
  return { id: `sub-${code}`, code, name, networkArea: 'Ostervik north', flowTemperatureC: 82 }
}

describe('SubstationTypeahead', () => {
  beforeEach(() => {
    mocked.mockReset()
  })

  it('keeps the slow earlier query from replacing the results for what was typed last', async () => {
    const user = userEvent.setup()
    let releaseSlowQuery: () => void = () => {}
    mocked.mockImplementation((query: string) =>
      query === 'SUB-1'
        ? new Promise<Substation[]>((resolve) => {
            releaseSlowQuery = () => resolve([substation('SUB-1', 'Havnegade primary')])
          })
        : Promise.resolve([substation('SUB-14', 'Kirkevej exchange')]),
    )

    render(<SubstationTypeahead onSelect={vi.fn()} />)
    const box = screen.getByLabelText('Substation code or name')
    await user.type(box, 'SUB-1')
    await user.type(box, '4')
    await waitFor(() => expect(screen.getByText('Kirkevej exchange')).toBeInTheDocument())

    releaseSlowQuery()
    await waitFor(() => expect(screen.getByText('Kirkevej exchange')).toBeInTheDocument())
    expect(screen.queryByText('Havnegade primary')).not.toBeInTheDocument()
  })

  it('aborts the in flight lookup when the query moves on', async () => {
    const user = userEvent.setup()
    mocked.mockImplementation(() => new Promise<Substation[]>(() => {}))

    render(<SubstationTypeahead onSelect={vi.fn()} />)
    await user.type(screen.getByLabelText('Substation code or name'), 'SUB')
    await user.type(screen.getByLabelText('Substation code or name'), '-14')

    const signals = mocked.mock.calls.map((call) => call[1] as AbortSignal)
    await waitFor(() => expect(signals[0].aborted).toBe(true))
    expect(signals[signals.length - 1].aborted).toBe(false)
  })

  it('hands the picked substation back to the caller', async () => {
    const user = userEvent.setup()
    const onSelect = vi.fn()
    mocked.mockResolvedValue([substation('SUB-14', 'Kirkevej exchange')])

    render(<SubstationTypeahead onSelect={onSelect} />)
    await user.type(screen.getByLabelText('Substation code or name'), 'SUB-14')
    await user.click(await screen.findByRole('button', { name: /Kirkevej exchange/ }))
    expect(onSelect).toHaveBeenCalledWith(expect.objectContaining({ code: 'SUB-14' }))
  })
})

