import type { Lease } from './types'
import { monthlyChargeUsd, terminationLabel } from './leaseFields'

const HEADERS = ['Lease ID', 'Route', 'Strands', 'Term end', 'Monthly charge', 'Termination note']

function csvCell(value: string): string {
  if (/[",\r\n]/.test(value)) {
    return `"${value.replace(/"/g, '""')}"`
  }
  return value
}

export function buildLeaseCsv(leases: Lease[]): string {
  const rows = leases.map((lease) => [
    lease.id,
    lease.route,
    String(lease.strandCount),
    lease.termEnd,
    monthlyChargeUsd(lease),
    terminationLabel(lease),
  ])

  return [HEADERS, ...rows].map((row) => row.map(csvCell).join(',')).join('\r\n')
}

