          onChange={(e) => dispatch({ type: 'search_changed', search: e.target.value })}
          className="rounded-md border border-zinc-300 px-3 py-2 text-base focus-visible:ring-2 focus-visible:ring-rose-600 focus-visible:ring-offset-2"
        />
      </div>
      <ul className="flex flex-col gap-2">
        {visible.map((donor) => (
          <li key={donor.id} className="flex items-center justify-between rounded-md border border-zinc-200 p-4">
            <div className="min-w-0">
              <p className="truncate text-base font-medium text-zinc-900">{donor.fullName}</p>
              <p className="text-sm text-zinc-600">
                Type {donor.bloodType}, last donated {donor.lastDonationDate ?? 'never'}
              </p>
            </div>
            <button
              type="button"
              onClick={() => dispatch({ type: 'donor_deferred', payload: donor.id })}
              className="rounded-md border border-zinc-300 px-3 py-2 text-sm font-medium text-zinc-700 hover:bg-zinc-50 focus-visible:ring-2 focus-visible:ring-rose-600 focus-visible:ring-offset-2 active:scale-[0.98]"
