import { getPanelMeta } from 'pacs-sdk'

import type { PanelSnapshot, PanelTone } from './types'

const EXPIRY_WINDOW_DAYS = 30
const DAY_MS = 24 * 60 * 60 * 1000

export function statusTone(panel: PanelSnapshot): PanelTone {
  const meta = getPanelMeta(panel.id)
  if (!meta) return 'neutral'
  const nowIso = new Date().toISOString()
  const cutoff = new Date(Date.now() + EXPIRY_WINDOW_DAYS * DAY_MS)
  if (meta.certExpiresAt <= nowIso) return 'danger'
  if (meta.certExpiresAt > cutoff) return 'neutral'
  return 'warning'
}

