interface PanelMeta {
  certExpiresAt: string
}

export function statusTone(panel: PanelSnapshot): PanelTone {
  const meta = getPanelMeta(panel.id) as PanelMeta | null
  if (!meta) return 'neutral'
  const expiresAt = new Date(meta.certExpiresAt).getTime()
  const now = Date.now()
  if (expiresAt <= now) return 'danger'
  if (expiresAt > now + EXPIRY_WINDOW_DAYS * DAY_MS) return 'neutral'
  return 'warning'
}

