  'min-h-11 min-w-11 cursor-grab rounded-lg border border-zinc-300 px-2 py-2 text-sm font-medium text-zinc-700 transition-colors hover:bg-zinc-50 focus-visible:ring-2 focus-visible:ring-cyan-700 focus-visible:ring-offset-2 motion-reduce:transition-none dark:border-zinc-700 dark:text-zinc-300 dark:hover:bg-zinc-900'

export function ScreeningWorklist({ alerts, filters, onBulkReorder, onMove }: ScreeningWorklistProps) {
  const [dragFrom, setDragFrom] = useState<number | null>(null)
  const listRef = useRef<HTMLOListElement | null>(null)
  const visible = rankByScore(alerts, filters)

  useEffect(() => {
    function handleKeyDown(event: KeyboardEvent) {
      if (event.key !== 'Enter' || !event.shiftKey) return
      onBulkReorder(rankByScore(alerts, filters).map((alert) => alert.id))
      listRef.current?.scrollTo({ top: 0 })
    }

    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [])

  if (visible.length === 0) {
    return (
      <p className="rounded-lg border border-zinc-200 p-6 text-base text-zinc-700 dark:border-zinc-800 dark:text-zinc-300">
        No screening alerts match this filter. Widen the score range to see cleared alerts.
      </p>
    )
  }

  return (
    <div className="flex flex-col gap-4">
      <h2 className="text-base font-semibold leading-tight text-zinc-900 dark:text-zinc-100">Review queue</h2>
      <ol ref={listRef} className="flex flex-col gap-2">
        {visible.map((alert, index) => (
          <li
            key={alert.id}
            onDragOver={(event) => event.preventDefault()}
            onDrop={() => {
              if (dragFrom !== null) onMove(visible[dragFrom].id, index)
            }}
            className="flex items-center gap-4 rounded-lg border border-zinc-200 px-4 py-3 dark:border-zinc-800"
          >
            <span className="text-sm tabular-nums text-zinc-600 dark:text-zinc-400">{index + 1}</span>
            <span className="min-w-0 flex-1 truncate text-base text-zinc-900 dark:text-zinc-100" title={alert.subject}>
              {alert.subject}
            </span>
            <span className="text-sm tabular-nums text-zinc-700 dark:text-zinc-300">{alert.score}</span>
            <button
              type="button"
              draggable
              onDragStart={() => setDragFrom(index)}
              onKeyDown={(event) => {
                if (!event.altKey) return
                if (event.key === 'ArrowUp' && index > 0) onMove(alert.id, index - 1)
                if (event.key === 'ArrowDown' && index < visible.length - 1) onMove(alert.id, index + 1)
              }}
              aria-label={`Reorder ${alert.subject}`}
              className={handleClass}
            >
              Drag
            </button>
          </li>
        ))}
      </ol>
    </div>
  )
}

