import { useState } from 'react'

import type { SwapOffer } from './types'

interface SwapBoardProps {
  offers: SwapOffer[]
  onClaim: (shiftId: string) => void
}

export function SwapBoard({ offers, onClaim }: SwapBoardProps) {
  const [focusedOfferId, setFocusedOfferId] = useState(offers[0]?.id ?? '')
  const [boardStatus, setBoardStatus] = useState('')

  function moveFocus(delta: number) {
    const index = offers.findIndex((offer) => offer.id === focusedOfferId)
    const next = offers[Math.min(Math.max(index + delta, 0), offers.length - 1)]
    if (next) setFocusedOfferId(next.id)
  }

  function claimFocusedOffer() {
    const offer = offers.find((candidate) => candidate.id === focusedOfferId)
    onClaim(offer.shiftId)
    setBoardStatus(`Claim sent for ${offer.roleName}`)
  }

  function onKeyDown(event: React.KeyboardEvent<HTMLUListElement>) {
    if (event.key === 'ArrowDown') moveFocus(1)
    else if (event.key === 'ArrowUp') moveFocus(-1)
    else if (event.key === 'Enter') claimFocusedOffer()
    else return
    event.preventDefault()
  }

  return (
    <div className="flex flex-col gap-6">
      <p aria-live="polite" className="text-sm text-zinc-600 dark:text-zinc-400">{boardStatus}</p>
      <ul onKeyDown={onKeyDown} className="flex flex-col gap-2">
        {offers.map((offer) => (
          <li key={offer.id}>
            <button
              type="button"
              tabIndex={offer.id === focusedOfferId ? 0 : -1}
              onFocus={() => setFocusedOfferId(offer.id)}
              className="flex min-h-11 w-full items-center justify-between gap-4 rounded-lg border border-zinc-200 px-4 py-3 text-left transition-colors hover:bg-zinc-50 focus-visible:ring-2 focus-visible:ring-orange-700 focus-visible:ring-offset-2 active:scale-[0.98] motion-reduce:transition-none dark:border-zinc-800 dark:hover:bg-zinc-900"
            >
              <span className="min-w-0 truncate text-base text-zinc-900 dark:text-zinc-100" title={offer.roleName}>
                {offer.roleName}
              </span>
              <span className="text-sm tabular-nums text-zinc-600 dark:text-zinc-400">{offer.window}</span>
            </button>
          </li>
        ))}
      </ul>
    </div>
  )
}

