import { render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { describe, expect, it, vi } from 'vitest'

import { SwapBoard } from './SwapBoard'

const offers = [
  { id: 'so-9012', shiftId: 'sh-3341', roleName: 'Late shift, ward host', window: 'Sun 14:00 - 22:00' },
  { id: 'so-9018', shiftId: 'sh-3352', roleName: 'Early shift, porter', window: 'Mon 06:00 - 14:00' },
]

describe('SwapBoard', () => {
  it('claims the highlighted offer on Enter', async () => {
    const user = userEvent.setup()
    const onClaim = vi.fn()
    render(<SwapBoard offers={offers} onClaim={onClaim} />)

    await user.tab()
    await user.keyboard('{Enter}')
    expect(onClaim).toHaveBeenCalledWith('sh-3341')
  })

  it('reports a claim on an offer that has left the board instead of crashing', async () => {
    const user = userEvent.setup()
    const onClaim = vi.fn()
    const { rerender } = render(<SwapBoard offers={offers} onClaim={onClaim} />)

    await user.tab()
    rerender(<SwapBoard offers={[offers[1]]} onClaim={onClaim} />)
    await user.keyboard('{Enter}')

    expect(onClaim).not.toHaveBeenCalled()
    expect(screen.getByText('That swap has already been taken. Showing what is left.')).toBeInTheDocument()
  })
})

