import { useRef, useState } from 'react'

import type { LedgerEntry } from '../types'
import { ROW_HEIGHT, visibleWindow } from './windowRows'

interface HistoryDrawerProps {
  stopeId: string
  entries: LedgerEntry[]
}

const VIEWPORT_HEIGHT = 448

const SURVEYED_ON = new Intl.DateTimeFormat('en-GB', {
  day: 'numeric',
  month: 'short',
  timeZone: 'UTC',
})

export function HistoryDrawer({ stopeId, entries }: HistoryDrawerProps) {
  const viewportRef = useRef<HTMLDivElement>(null)
  const [scrollTop, setScrollTop] = useState(0)

  const { startIndex, endIndex } = visibleWindow(entries.length, scrollTop, VIEWPORT_HEIGHT, ROW_HEIGHT)
  const windowed = entries.slice(startIndex, endIndex)

  return (
    <section className="flex flex-col gap-6">
      <div className="flex items-baseline justify-between gap-6">
        <h2 className="text-base font-semibold text-slate-900 dark:text-slate-100">
          Reconciliation history, stope {stopeId}
        </h2>
        <p className="text-sm tabular-nums text-slate-600 dark:text-slate-400">{entries.length} entries</p>
      </div>
      <div
        ref={viewportRef}
        onScroll={(event) => setScrollTop(event.currentTarget.scrollTop)}
        style={{ height: VIEWPORT_HEIGHT }}
        className="overflow-y-auto rounded-md border border-slate-200 dark:border-slate-800"
      >
        <ul style={{ height: entries.length * ROW_HEIGHT }} className="relative">
          {windowed.map((entry, offset) => (
            <li
              key={entry.id}
              style={{ top: (startIndex + offset) * ROW_HEIGHT, height: ROW_HEIGHT }}
              className="absolute inset-x-0 flex items-center justify-between gap-4 px-4"
            >
              <span className="min-w-0 truncate text-base text-slate-900 dark:text-slate-100" title={entry.note}>
                {entry.note}
              </span>
              <span className="shrink-0 text-sm tabular-nums text-slate-600 dark:text-slate-400">
                {entry.tonnes} t, {SURVEYED_ON.format(new Date(entry.surveyedAt))}
              </span>
            </li>
          ))}
        </ul>
      </div>
    </section>
  )
}

export const ROW_HEIGHT = 56

export interface RowWindow {
  startIndex: number
  endIndex: number
}

export function visibleWindow(
  total: number,
  scrollTop: number,
  viewportHeight: number,
  rowHeight: number,
): RowWindow {
  const startIndex = Math.max(0, Math.floor(scrollTop / rowHeight))
  const visibleCount = Math.ceil(viewportHeight / rowHeight)
  const endIndex = Math.min(total - 1, startIndex + visibleCount)
  return { startIndex, endIndex }
}

