describe('useCrewRowConfig', () => {
  it('hands back the same object when nothing a row cares about changed', () => {
    const { result, rerender } = renderHook(({ density }) => useCrewRowConfig(density, 'Europe/Madrid'), {
      initialProps: { density: 'comfortable' as const },
    })
    const first = result.current

    rerender({ density: 'comfortable' as const })

    expect(result.current).toBe(first)
  })

  it('hands back a new object when the density preference changes', () => {
    const { result, rerender } = renderHook(({ density }) => useCrewRowConfig(density, 'Europe/Madrid'), {
      initialProps: { density: 'comfortable' as const },
    })
    const first = result.current

    rerender({ density: 'compact' as const })

    expect(result.current).not.toBe(first)
    expect(result.current.density).toBe('compact')
  })

  it('leaves a memoized row alone while an unrelated control in the panel moves', () => {
    render(<Harness timeZone="Europe/Madrid" />)
    expect(rowRenders).toHaveBeenCalledTimes(1)

    fireEvent.click(screen.getByRole('button', { name: 'Quiet hours off' }))

    expect(screen.getByRole('button', { name: 'Quiet hours on' })).toBeInTheDocument()
    expect(rowRenders).toHaveBeenCalledTimes(1)
  })
})

