interface SampleWindow {
  slice: SampleRow[]
  offsetY: number
  totalHeight: number
}

export function useSampleWindow(rows: SampleRow[], scrollTop: number, viewportHeight: number, rowHeight = 32): SampleWindow {
  return useMemo(() => {
    const first = Math.max(0, Math.floor(scrollTop / rowHeight) - 4)
    const count = Math.ceil(viewportHeight / rowHeight) + 8
    return {
      slice: rows.slice(first, first + count),
      offsetY: first * rowHeight,
      totalHeight: rows.length * rowHeight,
    }
  }, [rows, scrollTop, viewportHeight, rowHeight])
}

