const [optimisticStatus, setOptimisticStatus] = useState<Payout['status'] | null>(null)
const [releasing, setReleasing] = useState(false)
const [failure, setFailure] = useState<string | null>(null)
const status = optimisticStatus ?? payout.status

async function handleRelease() {
  if (releasing || status !== 'pending') return
  setReleasing(true)
  setFailure(null)
  setOptimisticStatus('released')
  try {
    const updated = await releasePayout(payout.id)
    onReleased(updated)
  } catch {
    setOptimisticStatus(null)
    setFailure('The bank rejected the release, this payout is still pending.')
  } finally {
    setReleasing(false)
  }
}

