import { describe, expect, it } from 'vitest'

import { filterReadings } from './filterReadings'
import type { SurveyReading } from './types'

const readings: SurveyReading[] = [
  { kind: 'pressure', stationId: 'CP-118', takenAt: '2026-07-22T08:14:00Z', psi: 742 },
  { kind: 'pressure', stationId: 'CP-119', takenAt: '2026-07-22T08:41:00Z', psi: 610 },
  { kind: 'flow', stationId: 'CP-118', takenAt: '2026-07-22T09:02:00Z', gpm: 288 },
]

describe('filterReadings', () => {
  it('judges each reading kind on the field that kind actually carries', () => {
    const kept = filterReadings(readings, { kind: 'all', minPsi: 700, minGpm: 100 })
    expect(kept.map((reading) => reading.takenAt)).toEqual([
      '2026-07-22T08:14:00Z',
      '2026-07-22T09:02:00Z',
    ])
  })

  it('ignores the pressure floor when the run is filtered to flow', () => {
    const kept = filterReadings(readings, { kind: 'flow', minPsi: 9000, minGpm: 100 })
    expect(kept).toHaveLength(1)
    expect(kept[0].kind).toBe('flow')
  })

  it('drops a flow reading under the flow floor', () => {
    const kept = filterReadings(readings, { kind: 'flow', minPsi: 0, minGpm: 300 })
    expect(kept).toEqual([])
  })
})

