import type { FlagPayload, FlagRequestOptions } from './flagTypes'

const DEFAULT_TIMEOUT_MS = 2000

function payloadUrl(practiceId: string): string {
  return '/api/flags/payload?practice=' + encodeURIComponent(practiceId)
}

export async function fetchFlagPayload(
  practiceId: string,
  options: FlagRequestOptions = {},
): Promise<FlagPayload> {
  const request: FlagRequestOptions = {
    ...options,
    timeoutMs: DEFAULT_TIMEOUT_MS,
    retries: 1,
  }

  return requestWithTimeout<FlagPayload>(payloadUrl(practiceId), request)
}

