import { applyFanSetting } from '../api/applyFanSetting'
import type { VentilationSnapshot } from '../types'

function countFans(total: number) {
  return total + (total === 1 ? ' fan' : ' fans')
}

export async function restoreSnapshot(snapshot: VentilationSnapshot): Promise<string> {
  const results = await Promise.allSettled(
    snapshot.fans.map((fan) => applyFanSetting(fan.id, fan.setting)),
  )
  const refused = results.filter((result) => result.status === 'rejected').length
  const applied = results.length - refused

  if (refused === 0) {
    return countFans(applied) + ' set'
  }
  return countFans(applied) + ' set, ' + refused + ' refused'
}

import { beforeEach, describe, expect, it, vi } from 'vitest'

import { restoreSnapshot } from './restoreSnapshot'

const applyFanSetting = vi.hoisted(() => vi.fn())

vi.mock('../api/applyFanSetting', () => ({ applyFanSetting }))

const snapshot = {
  id: 'vs-618',
  takenAt: '2026-02-11T22:15:00Z',
  takenBy: 'Ingrid Solheim',
  fans: [
    { id: 'fan-1a', setting: 62 },
    { id: 'fan-1b', setting: 58 },
    { id: 'fan-3c', setting: 44 },
  ],
}

describe('restoreSnapshot', () => {
  beforeEach(() => {
    applyFanSetting.mockReset()
  })

  it('waits for every fan before it reports back', async () => {
    const finished: string[] = []
    applyFanSetting.mockImplementation(async (fanId: string) => {
      await new Promise((resolve) => setTimeout(resolve, 5))
      finished.push(fanId)
    })

    const message = await restoreSnapshot(snapshot)

    expect(finished).toEqual(['fan-1a', 'fan-1b', 'fan-3c'])
    expect(message).toBe('3 fans set')
  })

  it('counts the fans that refused instead of losing them', async () => {
    applyFanSetting.mockImplementation(async (fanId: string) => {
      if (fanId === 'fan-3c') {
        throw new Error('fan-3c is on local control at the substation')
      }
    })

    expect(await restoreSnapshot(snapshot)).toBe('2 fans set, 1 refused')
  })

  it('reads as one fan when a snapshot only holds one', async () => {
    applyFanSetting.mockResolvedValue(undefined)

    expect(await restoreSnapshot({ ...snapshot, fans: [{ id: 'fan-1a', setting: 62 }] })).toBe(
      '1 fan set',
    )
  })
})

