import { fetchValuation, finalizeAppraisal } from '../api'
import type { AppraisalDraft, AppraiserScopes } from '../types'

export function useAppraisalSubmit(scopes: AppraiserScopes) {
  const [progress, setProgress] = useState(0)
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [done, setDone] = useState(false)

  async function submit(draft: AppraisalDraft) {
    setSubmitting(true)
    setError(null)
    setProgress(10)

    try {
      if (!draft.vin) {
        setError('Enter the VIN before sending this appraisal to the desk.')
        return
      }
      setProgress(35)

      const valuation = await fetchValuation(draft.vin)
      setProgress(60)

      if (!scopes.canFinalize) {
        setError('Your role can price a trade-in but not finalize it. Send it to a desk manager.')
        return
      }

      await finalizeAppraisal(draft, valuation)
      setProgress(100)
      setDone(true)
    } finally {
      setSubmitting(false)
    }
  }

  return { submit, progress, submitting, error, done }
}

