import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

import { loadArchivePage } from './runArchive'

function run(runId: string) {
  return { runId, method: 'USP assay 42', injectedAt: '2026-07-13T22:05:00Z', columnSerial: 'CS-8873' }
}

function jsonOk(body: unknown) {
  return { ok: true, status: 200, json: async () => body } as Response
}

function failed(status: number) {
  return { ok: false, status, json: async () => ({}) } as Response
}

beforeEach(() => {
  vi.stubGlobal('fetch', vi.fn())
})

afterEach(() => {
  vi.unstubAllGlobals()
})

describe('loadArchivePage', () => {
  it('still returns the runs when the column stats service is down', async () => {
    vi.mocked(fetch).mockImplementation(async (input) =>
      String(input).includes('column-stats') ? failed(503) : jsonOk({ runs: [run('CH-20416')], nextCursor: null }),
    )

    const page = await loadArchivePage(null)

    expect(page.runs).toHaveLength(1)
    expect(page.stats).toBeNull()
    expect(page.nextCursor).toBeNull()
  })

  it('fails when the run page itself fails', async () => {
    vi.mocked(fetch).mockImplementation(async (input) =>
      String(input).includes('column-stats') ? jsonOk({ backpressureBar: 118, plateCount: 9400 }) : failed(500),
    )

    await expect(loadArchivePage(null)).rejects.toThrow('Run page request failed with status 500')
  })

  it('warms the next cursor so the second page needs no new request', async () => {
    const fetchMock = vi.mocked(fetch)
    fetchMock.mockImplementation(async (input) => {
      const url = String(input)
      if (url.includes('column-stats')) {
        return jsonOk({ backpressureBar: 118, plateCount: 9400 })
      }
      return url.includes('after=')
        ? jsonOk({ runs: [run('CH-20389')], nextCursor: null })
        : jsonOk({ runs: [run('CH-20416')], nextCursor: 'cur-8' })
    })

    const first = await loadArchivePage(null)
    expect(first.nextCursor).toBe('cur-8')
    expect(fetchMock).toHaveBeenCalledTimes(4)

    const second = await loadArchivePage('cur-8')
    expect(second.runs[0].runId).toBe('CH-20389')
    expect(second.nextCursor).toBeNull()
    expect(fetchMock).toHaveBeenCalledTimes(4)
  })
})

