import { useCallback, useEffect, useRef, useState } from 'react'

import { readCachedSnapshot, writeCachedSnapshot } from '../../offline/snapshotCache'
import { fetchSiteSnapshot } from './api'
import type { SiteSnapshot } from './types'

const RETRY_DELAY_MS = 4000

export function useSiteSnapshot(siteId: string) {
  const [snapshot, setSnapshot] = useState<SiteSnapshot | null>(null)
  const [error, setError] = useState<string | null>(null)
  const retryTimer = useRef<number | null>(null)

  const load = useCallback(async () => {
    setError(null)
    try {
      const fresh = await fetchSiteSnapshot(siteId)
      writeCachedSnapshot(siteId, fresh)
      setSnapshot(fresh)
    } catch {
      const cached = readCachedSnapshot(siteId)
      if (cached) {
        setSnapshot(cached)
      }
      setError('Sync failed for this site. Retrying in a few seconds.')
      retryTimer.current = window.setTimeout(() => {
        void load()
      }, RETRY_DELAY_MS)
    }
  }, [siteId])

  useEffect(() => {
    void load()
    return () => {
      if (retryTimer.current !== null) {
        window.clearTimeout(retryTimer.current)
      }
    }
  }, [load])

  return { snapshot, error, refresh: load }
}

