import { act, renderHook, waitFor } from '@testing-library/react'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

import { writeCachedSnapshot } from '../../offline/snapshotCache'
import { fetchSiteSnapshot } from './api'
import { useSiteSnapshot } from './useSiteSnapshot'

vi.mock('./api', () => ({ fetchSiteSnapshot: vi.fn() }))
vi.mock('../../offline/snapshotCache', () => ({
  readCachedSnapshot: vi.fn(() => null),
  writeCachedSnapshot: vi.fn(),
}))

const fetchMock = vi.mocked(fetchSiteSnapshot)
const writeMock = vi.mocked(writeCachedSnapshot)

const stale = { siteId: 'kalmar-ridge', windKph: 11, tempC: 14.6, takenAt: '2026-07-30T07:55:00Z' }
const fresh = { siteId: 'kalmar-ridge', windKph: 26, tempC: 12.1, takenAt: '2026-07-30T09:40:00Z' }

function deferred() {
  let resolve = (value: typeof fresh) => {
    void value
  }
  const promise = new Promise<typeof fresh>((r) => {
    resolve = r
  })
  return { promise, resolve }
}

beforeEach(() => {
  vi.useFakeTimers()
})

afterEach(() => {
  vi.useRealTimers()
  vi.clearAllMocks()
})

describe('useSiteSnapshot', () => {
  it('ignores a retry that lands after a newer request', async () => {
    const retry = deferred()
    const manual = deferred()
    fetchMock
      .mockRejectedValueOnce(new Error('offline'))
      .mockReturnValueOnce(retry.promise)
      .mockReturnValueOnce(manual.promise)

    const { result } = renderHook(() => useSiteSnapshot('kalmar-ridge'))
    await waitFor(() => expect(result.current.error).not.toBeNull())

    await act(async () => {
      vi.advanceTimersByTime(4000)
    })
    await act(async () => {
      void result.current.refresh()
    })
    await act(async () => {
      manual.resolve(fresh)
    })
    await act(async () => {
      retry.resolve(stale)
    })

    expect(result.current.snapshot).toEqual(fresh)
  })

  it('does not let a late retry rewrite the offline copy', async () => {
    const retry = deferred()
    const manual = deferred()
    fetchMock
      .mockRejectedValueOnce(new Error('offline'))
      .mockReturnValueOnce(retry.promise)
      .mockReturnValueOnce(manual.promise)

    const { result } = renderHook(() => useSiteSnapshot('kalmar-ridge'))
    await waitFor(() => expect(result.current.error).not.toBeNull())

    await act(async () => {
      vi.advanceTimersByTime(4000)
    })
    await act(async () => {
      void result.current.refresh()
    })
    await act(async () => {
      manual.resolve(fresh)
      retry.resolve(stale)
    })

    expect(writeMock).toHaveBeenCalledTimes(1)
    expect(writeMock).toHaveBeenCalledWith('kalmar-ridge', fresh)
  })

  it('still shows the newest payload when nothing raced', async () => {
    fetchMock.mockResolvedValueOnce(fresh)
    const { result } = renderHook(() => useSiteSnapshot('kalmar-ridge'))
    await waitFor(() => expect(result.current.snapshot).toEqual(fresh))
    expect(result.current.error).toBeNull()
  })
})

