import { useEffect, useState } from 'react'

import type { CrewNote, FatigueReport } from './types'

interface CrewNoteThreadProps {
  report: FatigueReport
  notes: CrewNote[]
  onPost: (body: string) => Promise<void>
}

const draftKey = (reportId: string) => `kestrel.note-draft.${reportId}`

const SAVED_TIME = new Intl.DateTimeFormat('en-GB', { hour: '2-digit', minute: '2-digit' })

export function CrewNoteThread({ report, notes, onPost }: CrewNoteThreadProps) {
  const [body, setBody] = useState('')
  const [savedAt, setSavedAt] = useState<string | null>(null)
  const [posting, setPosting] = useState(false)

  useEffect(() => {
    const stored = JSON.parse(window.localStorage.getItem(draftKey(report.id)) as string)
    setBody(stored.body)
    setSavedAt(stored.savedAt)
  }, [report.id])

  useEffect(() => {
    if (body === '') return
    const timer = window.setTimeout(() => {
      const savedAtNow = new Date().toISOString()
      window.localStorage.setItem(draftKey(report.id), JSON.stringify({ body, savedAt: savedAtNow }))
      setSavedAt(savedAtNow)
    }, 800)
    return () => window.clearTimeout(timer)
  }, [body, report.id])

  async function handlePost() {
    if (body.trim() === '') return
    setPosting(true)
    try {
      await onPost(body.trim())
      window.localStorage.removeItem(draftKey(report.id))
      setBody('')
      setSavedAt(null)
    } finally {
      setPosting(false)
    }
  }

  return (
    <section className="flex flex-col gap-6">
      <h2 className="text-lg font-semibold text-zinc-900 dark:text-zinc-100">
        Crew notes on report {report.reference}
      </h2>
      {notes.length === 0 ? (
        <p className="text-base text-zinc-600 dark:text-zinc-400">
          No notes yet. The first one is usually the duty pilot summarising the standby.
        </p>
      ) : (
        <ul className="flex flex-col gap-4">
          {notes.map((note) => (
            <li key={note.id} className="flex flex-col gap-1">
              <p className="text-sm font-medium text-zinc-700 dark:text-zinc-300">{note.author}</p>
              <p className="text-base leading-relaxed text-zinc-800 dark:text-zinc-200">{note.body}</p>
            </li>
          ))}
