export interface NoteDraft {
  body: string
  savedAt: string
}

function draftKey(reportId: string) {
  return `kestrel.note-draft.${reportId}`
}

export function readDraft(reportId: string): NoteDraft | null {
  const raw = window.localStorage.getItem(draftKey(reportId))
  if (raw === null) return null
  try {
    const parsed: unknown = JSON.parse(raw)
    if (typeof parsed !== 'object' || parsed === null) return null
    const { body, savedAt } = parsed as Partial<NoteDraft>
    if (typeof body !== 'string' || typeof savedAt !== 'string') return null
    return { body, savedAt }
  } catch {
    return null
  }
}

export function writeDraft(reportId: string, draft: NoteDraft) {
  window.localStorage.setItem(draftKey(reportId), JSON.stringify(draft))
}

export function clearDraft(reportId: string) {
  window.localStorage.removeItem(draftKey(reportId))
}

import { beforeEach, describe, expect, it } from 'vitest'

import { clearDraft, readDraft, writeDraft } from './noteDraft'

const REPORT = 'fr-70412'
const draft = {
  body: 'Four hours standby before the sector, felt it on the descent into FAO.',
  savedAt: '2026-03-14T09:12:00.000Z',
}

beforeEach(() => {
  window.localStorage.clear()
})

describe('readDraft', () => {
  it('returns null for a report nobody has drafted on yet', () => {
    expect(readDraft(REPORT)).toBeNull()
  })

  it('returns null instead of throwing when the stored value is not JSON', () => {
    window.localStorage.setItem('kestrel.note-draft.fr-70412', 'standby 4h then FAO')
    expect(readDraft(REPORT)).toBeNull()
  })

  it('returns null when the stored JSON is not a draft', () => {
    window.localStorage.setItem('kestrel.note-draft.fr-70412', '{"body":42}')
    expect(readDraft(REPORT)).toBeNull()
  })

  it('gives back the draft that was written for that report', () => {
    writeDraft(REPORT, draft)
    expect(readDraft(REPORT)).toEqual(draft)
  })

  it('forgets the draft once it has been cleared', () => {
    writeDraft(REPORT, draft)
    clearDraft(REPORT)
    expect(readDraft(REPORT)).toBeNull()
  })
})

import { useEffect, useState } from 'react'

import { clearDraft, readDraft, writeDraft } from './noteDraft'
import type { CrewNote, FatigueReport } from './types'

interface CrewNoteThreadProps {
  report: FatigueReport
  notes: CrewNote[]
  onPost: (body: string) => Promise<void>
}

const SAVED_TIME = new Intl.DateTimeFormat('en-GB', { hour: '2-digit', minute: '2-digit' })

export function CrewNoteThread({ report, notes, onPost }: CrewNoteThreadProps) {
  const [body, setBody] = useState('')
  const [savedAt, setSavedAt] = useState<string | null>(null)
  const [posting, setPosting] = useState(false)

  useEffect(() => {
    const stored = readDraft(report.id)
    setBody(stored?.body ?? '')
    setSavedAt(stored?.savedAt ?? null)
  }, [report.id])

  useEffect(() => {
    if (body === '') return
    const timer = window.setTimeout(() => {
      const savedAtNow = new Date().toISOString()
      writeDraft(report.id, { body, savedAt: savedAtNow })
      setSavedAt(savedAtNow)
    }, 800)
    return () => window.clearTimeout(timer)
  }, [body, report.id])

  async function handlePost() {
    if (body.trim() === '') return
    setPosting(true)
    try {
      await onPost(body.trim())
      clearDraft(report.id)
      setBody('')
      setSavedAt(null)
    } finally {
      setPosting(false)
    }
  }

  return (
    <section className="flex flex-col gap-6">
      <h2 className="text-lg font-semibold text-zinc-900 dark:text-zinc-100">
        Crew notes on report {report.reference}
      </h2>
