        <p className="text-base text-zinc-600 dark:text-zinc-400">
          No notes yet. The first one is usually the duty pilot summarising the standby.
        </p>
      ) : (
        <ul className="flex flex-col gap-4">
          {notes.map((note) => (
            <li key={note.id} className="flex flex-col gap-1">
              <p className="text-sm font-medium text-zinc-700 dark:text-zinc-300">{note.author}</p>
              <p className="text-base leading-relaxed text-zinc-800 dark:text-zinc-200">{note.body}</p>
            </li>
          ))}
        </ul>
      )}
      <div className="flex flex-col gap-2">
        <label htmlFor="crew-note" className="text-sm font-medium text-zinc-700 dark:text-zinc-300">
          Add a note
        </label>
        <textarea
          id="crew-note"
          value={body}
          onChange={(event) => setBody(event.target.value)}
          rows={5}
          className="rounded-md border border-zinc-300 px-4 py-2 text-base leading-relaxed text-zinc-900 focus-visible:ring-2 focus-visible:ring-orange-700 focus-visible:ring-offset-2 dark:border-zinc-700 dark:bg-zinc-950 dark:text-zinc-100"
        />
        <p aria-live="polite" className="text-sm tabular-nums text-zinc-600 dark:text-zinc-400">
          {savedAt === null ? 'Nothing saved yet' : `Draft saved ${SAVED_TIME.format(new Date(savedAt))}`}
        </p>
      </div>
      <button
        type="button"
        onClick={handlePost}
        disabled={posting || body.trim() === ''}
        className="self-start rounded-md bg-orange-700 px-4 py-2 text-base font-medium text-zinc-50 hover:bg-orange-800 focus-visible:ring-2 focus-visible:ring-orange-700 focus-visible:ring-offset-2 active:scale-[0.98] disabled:opacity-50 disabled:pointer-events-none dark:bg-orange-600 dark:hover:bg-orange-500"
      >
        {posting ? 'Posting...' : 'Post note'}
      </button>
    </section>
  )
}

