import { useEffect, useState } from 'react'

import { loadAgendaItems } from '../../api/minutes'
import type { AgendaItem } from './types'

interface AgendaBuilderProps {
  meetingId: string
  onSaveOrder: (itemIds: string[]) => void
}

const handleClass =
  'min-h-11 min-w-11 cursor-grab rounded-lg border border-zinc-300 px-2 py-2 text-sm font-medium text-zinc-700 transition-colors hover:bg-zinc-50 focus-visible:ring-2 focus-visible:ring-sky-700 focus-visible:ring-offset-2 motion-reduce:transition-none dark:border-zinc-700 dark:text-zinc-300 dark:hover:bg-zinc-900'

export function AgendaBuilder({ meetingId, onSaveOrder }: AgendaBuilderProps) {
  const [items, setItems] = useState<AgendaItem[]>([])
  const [dragFrom, setDragFrom] = useState<number | null>(null)
  const query = { meetingId, section: 'agenda' }

  useEffect(() => {
    void loadAgendaItems(query).then(setItems)
  }, [query])

  function move(from: number, to: number) {
    if (to < 0 || to >= items.length) return
    setItems((current) => {
      const next = current.slice()
      const [moved] = next.splice(from, 1)
      next.splice(to, 0, moved)
      return next
    })
  }

  return (
    <div className="flex flex-col gap-6">
      <h2 className="text-base font-semibold leading-tight text-zinc-900 dark:text-zinc-100">Agenda order</h2>
      {items.length === 0 ? (
        <p className="min-h-32 rounded-lg border border-zinc-200 p-6 text-base text-zinc-700 dark:border-zinc-800 dark:text-zinc-300">
          No agenda items on this meeting yet. Add an item to start building the running order.
        </p>
      ) : (
        <ol className="flex flex-col gap-2">
          {items.map((item, index) => (
            <li
              key={item.id}
              className="flex items-center gap-4 rounded-lg border border-zinc-200 px-4 py-3 dark:border-zinc-800"
            >
              <span className="text-sm tabular-nums text-zinc-600 dark:text-zinc-400">{index + 1}</span>
              <span className="min-w-0 flex-1 truncate text-base text-zinc-900 dark:text-zinc-100" title={item.title}>
                {item.title}
              </span>
              <span className="text-sm tabular-nums text-zinc-600 dark:text-zinc-400">{item.minutes} min</span>
              <button
                type="button"
                draggable
                onDragStart={() => setDragFrom(index)}
                onDragOver={(event) => event.preventDefault()}
                onDrop={() => {
                  if (dragFrom !== null) move(dragFrom, index)
                }}
                onKeyDown={(event) => {
                  if (!event.altKey) return
                  if (event.key === 'ArrowUp') move(index, index - 1)
                  if (event.key === 'ArrowDown') move(index, index + 1)
                }}
                aria-label={`Reorder ${item.title}, hold alt and press the arrow keys to move it`}
                className={handleClass}
              >
                Drag
              </button>
            </li>
          ))}
        </ol>
      )}
    </div>
  )
}

