import { describe, expect, it } from 'vitest'

import { nextMatchIndex } from './typeahead'

const names = [
  'Aisha Bello',
  'Dermot Quinn',
  'Femi Adeyemi',
  'Halina Nowak',
  'Ravi Shanmugam',
  'Yusuf Kaya',
]

describe('nextMatchIndex', () => {
  it('wraps from the last name back round to an earlier match', () => {
    expect(nextMatchIndex(names, 'd', 5)).toBe(1)
  })

  it('returns -1 when nothing in the list matches', () => {
    expect(nextMatchIndex(names, 'z', 2)).toBe(-1)
  })

  it('finds the next match below the cursor before wrapping', () => {
    expect(nextMatchIndex(names, 'r', 0)).toBe(4)
  })
})

