interface RebookingNoteDockProps {
  flight: DisruptedFlight
  onPosted: (body: string) => void
}

export function RebookingNoteDock({ flight, onPosted }: RebookingNoteDockProps) {
  const [draft, setDraft] = useState('')
  const [posting, setPosting] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const autosaveTimer = useRef<number | null>(null)
  const flightKey = `${flight.number}-${flight.serviceDate}`

  function scheduleAutosave(next: string) {
    if (autosaveTimer.current !== null) window.clearTimeout(autosaveTimer.current)
    autosaveTimer.current = window.setTimeout(() => {
      void saveNote({ flightKey, body: next, status: 'draft' })
    }, 600)
  }

  async function handlePost() {
    if (draft.trim() === '') return
    setPosting(true)
    setError(null)
    try {
      await saveNote({ flightKey, body: draft, status: 'posted' })
      onPosted(draft)
      setDraft('')
    } catch {
      setError('The note did not reach the desk. Check the connection and post it again.')
    } finally {
      setPosting(false)
    }
  }

  return (
    <section className="flex flex-col gap-4">
      <label htmlFor="rebooking-note" className="text-sm font-medium text-gray-700 dark:text-gray-300">
