import { useState } from 'react'

import type { CrateTrack } from '../types/crate'

interface CrateReorderListProps {
  initialTracks: CrateTrack[]
  onCommit: (trackIds: string[]) => void
}

export function CrateReorderList({ initialTracks, onCommit }: CrateReorderListProps) {
  const [tracks, setTracks] = useState<CrateTrack[]>(initialTracks)
  const [draggingId, setDraggingId] = useState<string | null>(null)

  function moveTrack(from: number, to: number) {
    const next = tracks
    const moved = next[from]
    next.splice(from, 1)
    next.splice(to, 0, moved)
    setTracks(next)
    onCommit(next.map((track) => track.id))
  }

  return (
    <ul className="flex flex-col gap-2">
      {tracks.map((track, index) => (
        <li
          key={track.id}
          draggable
          onDragStart={() => setDraggingId(track.id)}
          onDragOver={(event) => event.preventDefault()}
          onDrop={() => moveTrack(tracks.findIndex((item) => item.id === draggingId), index)}
          className="flex items-center gap-4 rounded-md border border-zinc-200 p-4 text-base text-zinc-900"
        >
          <span className="w-6 text-sm text-zinc-500">{index + 1}</span>
          <span className="min-w-0 truncate">{track.artist} - {track.title}</span>
          <span className="ml-auto text-sm text-zinc-500">{track.bpm} BPM</span>
        </li>
      ))}
    </ul>
  )
}

