import { useState } from 'react'

import { notifyToast } from '../../shared/notify'
import { saveRegistryOrder } from './api'
import type { RegistryItem } from './types'

interface RegistryEditorProps {
  registryId: string
  items: RegistryItem[]
}

const rowActionClass =
  'min-h-11 rounded-lg border border-zinc-300 px-4 py-2 text-sm font-medium text-zinc-900 transition-colors hover:bg-zinc-50 focus-visible:ring-2 focus-visible:ring-rose-700 focus-visible:ring-offset-2 active:scale-[0.98] disabled:pointer-events-none disabled:opacity-50 motion-reduce:transition-none dark:border-zinc-700 dark:text-zinc-100 dark:hover:bg-zinc-900'

export function RegistryEditor({ registryId, items }: RegistryEditorProps) {
  const [order, setOrder] = useState(items)
  const [savingKey, setSavingKey] = useState<string | null>(null)

  async function applyOrder(pendingKey: string, next: RegistryItem[], done: string) {
    const previous = order
    setOrder(next)
    setSavingKey(pendingKey)
    try {
      await saveRegistryOrder(registryId, next.map((item) => item.id))
      notifyToast('success', done)
    } catch {
      setOrder(previous)
      notifyToast('error', 'The registry service did not answer. Your order was left as it was, try again.')
    } finally {
      setSavingKey(null)
    }
  }

  return (
    <div className="flex flex-col gap-6">
      <ul className="flex flex-col gap-2">
        {order.map((item) => (
          <li key={item.id} className="flex items-center justify-between gap-4 rounded-lg border border-zinc-200 px-4 py-3 dark:border-zinc-800">
            <span className="min-w-0 truncate text-base text-zinc-900 dark:text-zinc-100" title={item.name}>{item.name}</span>
            <button
              type="button"
              disabled={savingKey !== null}
              onClick={() => {
                void applyOrder(item.id, [
                  ...order.filter((entry) => entry.id === item.id),
                  ...order.filter((entry) => entry.id !== item.id),
                ], 'Registry order saved')
              }}
              className={rowActionClass}
            >
              {savingKey === item.id ? 'Saving' : 'Move to top'}
            </button>
          </li>
        ))}
      </ul>
      <button
        type="button"
        disabled={savingKey !== null}
        onClick={() => {
          void applyOrder('suggested', items, 'Suggested order restored')
        }}
        className="self-start rounded-lg px-4 py-2 text-sm font-medium text-rose-700 underline transition-colors hover:text-rose-800 focus-visible:ring-2 focus-visible:ring-rose-700 focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 motion-reduce:transition-none dark:text-rose-400 dark:hover:text-rose-300"
      >
        Restore suggested order
      </button>
    </div>
  )
}

import { render, screen, waitFor } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { beforeEach, describe, expect, it, vi } from 'vitest'

import { RegistryEditor } from './RegistryEditor'

const notifySpy = vi.fn()
let settle: (() => void) | null = null

vi.mock('../../shared/notify', () => ({
  notifyToast: (tone: string, message: string) => notifySpy(tone, message),
}))

vi.mock('./api', () => ({
