import { render, screen, waitFor } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { afterEach, describe, expect, it, vi } from 'vitest'

import { fetchConditionScore, saveDamageSurvey } from '../../../api/conditionReports'
import { DamageSurveyStep } from './DamageSurveyStep'

vi.mock('../../../api/conditionReports', () => ({
  saveDamageSurvey: vi.fn(),
  fetchConditionScore: vi.fn(),
}))

const initialSurvey = { notes: 'Foxing across the fore-edge margin.', bindingState: 'sound' as const, score: null }

afterEach(() => {
  vi.clearAllMocks()
})

describe('DamageSurveyStep', () => {
  it('keeps notes typed while the save is in flight', async () => {
    const user = userEvent.setup()
    let releaseSave = () => {}
    vi.mocked(saveDamageSurvey).mockImplementation(
      () => new Promise<void>((resolve) => { releaseSave = resolve }),
    )
    vi.mocked(fetchConditionScore).mockResolvedValue(62)

    render(<DamageSurveyStep reportId="cr-7741" initialSurvey={initialSurvey} onContinue={vi.fn()} />)
    await user.click(screen.getByRole('button', { name: 'Save and continue' }))

    const notes = screen.getByLabelText('Damage notes')
    await user.type(notes, ' Tear at head of spine, 40mm.')
    releaseSave()

    await waitFor(() => expect(fetchConditionScore).toHaveBeenCalledWith('cr-7741'))
    await waitFor(() => expect(notes).toHaveValue(
      'Foxing across the fore-edge margin. Tear at head of spine, 40mm.',
    ))
  })

  it('surfaces a failed save without clearing the survey', async () => {
    const user = userEvent.setup()
    vi.mocked(saveDamageSurvey).mockRejectedValue(new Error('The condition register is not accepting writes.'))

    render(<DamageSurveyStep reportId="cr-7741" initialSurvey={initialSurvey} onContinue={vi.fn()} />)
    await user.click(screen.getByRole('button', { name: 'Save and continue' }))

    expect(await screen.findByRole('alert')).toHaveTextContent('The condition register is not accepting writes.')
    expect(screen.getByLabelText('Damage notes')).toHaveValue('Foxing across the fore-edge margin.')
  })
})

