import { useRef, useState } from 'react'
import type { KeyboardEvent } from 'react'

import type { KeySlot } from './types'

interface KeySlotGridProps {
  slots: KeySlot[]
  onOpenSlot: (slotId: string) => void
}

export function KeySlotGrid({ slots, onOpenSlot }: KeySlotGridProps) {
  const [activeIndex, setActiveIndex] = useState(0)
  const slotRefs = useRef<Array<HTMLButtonElement | null>>([])

  function focusSlot(index: number) {
    setActiveIndex(index)
    slotRefs.current[index]?.focus()
  }

  function handleKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (event.key === 'ArrowRight') {
      event.preventDefault()
      focusSlot(activeIndex === slots.length ? 0 : activeIndex + 1)
    }
    if (event.key === 'ArrowLeft') {
      event.preventDefault()
      focusSlot(activeIndex === 0 ? slots.length : activeIndex - 1)
    }
  }

  if (slots.length === 0) {
    return (
      <p className="rounded-xl border border-zinc-200 p-6 text-base leading-relaxed text-zinc-700 dark:border-zinc-800 dark:text-zinc-300">
        No slots mapped for this cabinet. Scan the slot labels to build the layout.
      </p>
    )
  }

  return (
    <div
      role="group"
      aria-label="Key slots"
      onKeyDown={handleKeyDown}
      className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4"
    >
      {slots.map((slot, index) => (
        <button
          key={slot.id}
          ref={(node) => { slotRefs.current[index] = node }}
          type="button"
          tabIndex={index === activeIndex ? 0 : -1}
          onClick={() => onOpenSlot(slot.id)}
          className="flex min-h-11 flex-col items-start gap-2 rounded-xl border border-zinc-200 bg-white p-4 text-left transition-colors hover:bg-zinc-50 focus-visible:ring-2 focus-visible:ring-amber-600 focus-visible:ring-offset-2 active:scale-[0.98] motion-reduce:transition-none dark:border-zinc-800 dark:bg-zinc-900 dark:hover:bg-zinc-800"
        >
          <span className="text-sm font-medium tabular-nums text-zinc-600 dark:text-zinc-400">
            Slot {index + 1}
          </span>
          <span className="min-w-0 truncate text-base font-medium text-zinc-900 dark:text-zinc-100" title={slot.keyName}>
            {slot.keyName}
          </span>
          <span className="text-sm text-zinc-600 dark:text-zinc-400">
            {slot.holderName ?? 'In cabinet'}
          </span>
        </button>
      ))}
    </div>
  )
}

