import { fireEvent, render, screen } from '@testing-library/react'
import { describe, expect, it, vi } from 'vitest'

import { KeySlotGrid } from './KeySlotGrid'

const slots = [
  { id: 'slot-1', keyName: 'Roof hatch', holderName: null },
  { id: 'slot-2', keyName: 'Gate 4 padlock', holderName: 'Owen Brathwaite' },
  { id: 'slot-3', keyName: 'Fuel store', holderName: null },
]

describe('KeySlotGrid roving focus', () => {
  it('wraps from the last slot back to the first', () => {
    render(<KeySlotGrid slots={slots} onOpenSlot={vi.fn()} />)
    const grid = screen.getByRole('group', { name: 'Key slots' })

    fireEvent.keyDown(grid, { key: 'ArrowRight' })
    fireEvent.keyDown(grid, { key: 'ArrowRight' })
    fireEvent.keyDown(grid, { key: 'ArrowRight' })

    expect(screen.getByRole('button', { name: /Roof hatch/ })).toHaveFocus()
  })

  it('wraps from the first slot back to the last', () => {
    render(<KeySlotGrid slots={slots} onOpenSlot={vi.fn()} />)
    const grid = screen.getByRole('group', { name: 'Key slots' })

    fireEvent.keyDown(grid, { key: 'ArrowLeft' })

    expect(screen.getByRole('button', { name: /Fuel store/ })).toHaveFocus()
  })
})

