import { useIntervalLog } from '../useIntervalLog'
import type { CoreRevision } from '../types'

interface RevisionHistoryProps {
  intervalId: string
}

const LOGGED_DAY = new Intl.DateTimeFormat('en-AU', {
  day: 'numeric',
  month: 'short',
  year: 'numeric',
  timeZone: 'Australia/Perth',
})

const TIME_OF_DAY = new Intl.DateTimeFormat('en-AU', {
  hour: '2-digit',
  minute: '2-digit',
  hour12: false,
  timeZone: 'Australia/Perth',
})

function describeChange(revision: CoreRevision) {
  return revision.changedFields.join(', ')
}

export function RevisionHistory({ intervalId }: RevisionHistoryProps) {
  const { revisions, restoreRevision } = useIntervalLog(intervalId)

  if (revisions.length === 0) {
    return (
      <p className="text-base leading-relaxed text-stone-600 dark:text-stone-400">
        Nothing saved yet. Save this interval once and every later edit is kept here.
      </p>
    )
  }

  return (
    <section className="flex flex-col gap-6">
      <div className="flex items-center justify-between gap-6">
        <h3 className="text-base font-semibold text-stone-900 dark:text-stone-100">
          Saved versions
        </h3>
        <button
          type="button"
          onClick={() => restoreRevision(revisions[0].id)}
          className="rounded-md border border-stone-300 px-4 py-2 text-sm font-medium text-stone-900 hover:bg-stone-100 focus-visible:ring-2 focus-visible:ring-amber-700 focus-visible:ring-offset-2 active:scale-[0.98] dark:border-stone-700 dark:text-stone-100 dark:hover:bg-stone-900"
        >
          Restore the last saved version
        </button>
      </div>
      <ul className="flex flex-col gap-2">
        {revisions.map((revision) => (
          <li
            key={LOGGED_DAY.format(new Date(revision.savedAt))}
            className="flex items-center justify-between gap-4 rounded-md border border-stone-200 px-4 py-2 dark:border-stone-800"
          >
            <div className="flex min-w-0 flex-col gap-2">
              <span
                className="truncate text-base text-stone-900 dark:text-stone-100"
                title={describeChange(revision)}
              >
                {describeChange(revision)}
              </span>
              <span className="text-sm text-stone-600 dark:text-stone-400">
                {revision.loggedBy}, {LOGGED_DAY.format(new Date(revision.savedAt))} at{' '}
                <span className="tabular-nums">{TIME_OF_DAY.format(new Date(revision.savedAt))}</span>
              </span>
            </div>
          </li>
        ))}
      </ul>
    </section>
  )
