export type DownloadResult = { ok: true } | { ok: false; message: string }

export function downloadOutageReport(blob: Blob, filename: string): DownloadResult {
  if (!filename.endsWith('.pdf')) {
    return { ok: false, message: 'The report file name must end in .pdf' }
  }

  const url = URL.createObjectURL(blob)
  try {
    const anchor = document.createElement('a')
    anchor.href = url
    anchor.download = filename
    anchor.click()
    return { ok: true }
  } finally {
    URL.revokeObjectURL(url)
  }
}

export function outageReportFilename(network: string, quarter: string): string {
  const slug = network.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')
  return `outage-report-${slug}-${quarter}.pdf`
}

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

import { downloadOutageReport, outageReportFilename } from './reportDownload'

const created: string[] = []
const revoked: string[] = []

beforeEach(() => {
  created.length = 0
  revoked.length = 0
  vi.stubGlobal('URL', {
    createObjectURL: () => {
      const url = `blob:almanac/${created.length}`
      created.push(url)
      return url
    },
    revokeObjectURL: (url: string) => {
      revoked.push(url)
    },
  })
})

afterEach(() => {
  vi.unstubAllGlobals()
})

describe('downloadOutageReport', () => {
  it('releases the object URL once the download has started', () => {
    const result = downloadOutageReport(new Blob(['%PDF-1.7']), 'outage-report-metro-east-2026q2.pdf')

    expect(result).toEqual({ ok: true })
    expect(revoked).toEqual(created)
  })

  it('holds on to nothing when the report name is rejected', () => {
    const result = downloadOutageReport(new Blob(['%PDF-1.7']), 'outage-report-metro-east-2026q2.txt')

    expect(result).toEqual({ ok: false, message: 'The report file name must end in .pdf' })
    expect(created).toEqual([])
    expect(revoked).toEqual([])
  })
})

describe('outageReportFilename', () => {
  it('slugs the network name and keeps the quarter readable', () => {
    expect(outageReportFilename('Metro East / Ring 4', '2026q2')).toBe('outage-report-metro-east-ring-4-2026q2.pdf')
  })
})

