import { act, renderHook, waitFor } from '@testing-library/react'
import { describe, expect, it, vi } from 'vitest'

import { useRetrySave } from './retrySave'

const prefs = { deckId: 'deck-7', armWarningSeconds: 30, confirmEachStep: true }

function deferred() {
  let resolve: () => void = () => {}
  const promise = new Promise<void>((settle) => {
    resolve = () => settle()
  })
  return { promise, resolve }
}

describe('useRetrySave', () => {
  it('sends one save even when Retry is tapped three times', async () => {
    const pending = deferred()
    const save = vi.fn().mockReturnValue(pending.promise)
    const { result } = renderHook(() => useRetrySave(save))

    act(() => {
      void result.current.retry(prefs)
      void result.current.retry(prefs)
      void result.current.retry(prefs)
    })

    expect(save).toHaveBeenCalledTimes(1)

    await act(async () => {
      pending.resolve()
    })
    await waitFor(() => expect(result.current.status).toBe('idle'))
  })

  it('lets the deck lead retry again once the first attempt has finished', async () => {
    const save = vi.fn().mockRejectedValueOnce(new Error('offline')).mockResolvedValueOnce(undefined)
    const { result } = renderHook(() => useRetrySave(save))

    await act(async () => {
      await result.current.retry(prefs)
    })
    expect(result.current.status).toBe('failed')

    await act(async () => {
      await result.current.retry(prefs)
    })

    expect(save).toHaveBeenCalledTimes(2)
    expect(result.current.status).toBe('idle')
  })
})

