import { useState } from 'react'

import { putPreference } from '../../lib/preferencesApi'
import type { AppearanceDraft } from './types'

const SAVE_ORDER = ['theme', 'density', 'textScale'] as const

export function useAppearanceSave() {
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)

  async function save(guardId: string, draft: AppearanceDraft) {
    setSaving(true)
    setError(null)
    try {
      for (const key of SAVE_ORDER) {
        putPreference(guardId, key, draft[key])
      }
    } catch {
      setError('Could not save the display settings. Check the handset signal and try again.')
    } finally {
      setSaving(false)
    }
  }

  return { save, saving, error }
}

