import type { DigitizationBatchRequest, IssueDay } from './types'

const LONG_DAY = new Intl.DateTimeFormat('en-GB', {
  day: 'numeric',
  month: 'long',
  year: 'numeric',
  timeZone: 'UTC',
})

export function eachIssueDay(fromDay: string, toDay: string) {
  const days: string[] = []
  const cursor = new Date(fromDay + 'T00:00:00Z')
  const last = new Date(toDay + 'T00:00:00Z')
  while (cursor <= last) {
    days.push(cursor.toISOString().slice(0, 10))
    cursor.setUTCDate(cursor.getUTCDate() + 1)
  }
  return days
}

export function countIssuesInRange(availableDays: IssueDay[], fromDay: string, toDay: string) {
  return availableDays.filter((day) => day.publishedOn >= fromDay && day.publishedOn <= toDay).length
}

export function summarizeRange(availableDays: IssueDay[], fromDay: string, toDay: string) {
  return (
    countIssuesInRange(availableDays, fromDay, toDay) +
    ' issues, ' +
    LONG_DAY.format(new Date(fromDay + 'T00:00:00Z')) +
    ' to ' +
    LONG_DAY.format(new Date(toDay + 'T00:00:00Z')) +
    ' inclusive'
  )
}

export function buildBatchRequest(titleId: string, fromDay: string, toDay: string): DigitizationBatchRequest {
  return { titleId, fromDay, toDayExclusive: toDay }
}

import { describe, expect, it } from 'vitest'

import { buildBatchRequest, eachIssueDay, summarizeRange } from './issueRange'

const sanduskyDays = [
  { publishedOn: '1948-03-03', reelId: 'r-4412' },
  { publishedOn: '1948-03-04', reelId: 'r-4412' },
  { publishedOn: '1948-03-05', reelId: 'r-4412' },
