  { publishedOn: '1948-03-11', reelId: 'r-4414' },
  { publishedOn: '1948-03-12', reelId: 'r-4414' },
  { publishedOn: '1948-03-13', reelId: 'r-4414' },
]

describe('issueRange', () => {
  it('lists every day between the two dates the reading room typed', () => {
    const days = eachIssueDay('1948-03-03', '1948-03-12')
    expect(days).toHaveLength(10)
    expect(days.at(-1)).toBe('1948-03-12')
  })

  it('describes the run the way the confirmation copy promises it', () => {
    expect(summarizeRange(sanduskyDays, '1948-03-03', '1948-03-12')).toBe(
      '10 issues, 3 March 1948 to 12 March 1948 inclusive',
    )
  })

  it('asks the scanner for a window that still contains the last day', () => {
    const request = buildBatchRequest('sandusky-register', '1948-03-03', '1948-03-12')
    expect(request.toDayExclusive).toBe('1948-03-13')
  })
})

