import { memo } from 'react'

import type { AssayRun } from './types'

interface AssayRunRowProps {
  run: AssayRun
  onOpen: (runId: string) => void
}

const QC_LABELS: Record<AssayRun['qcState'], string> = {
  released: 'Released',
  second_review: 'Second review',
  on_hold: 'On hold',
}

function sameRun(prev: AssayRunRowProps, next: AssayRunRowProps) {
  return (
    prev.run.id === next.run.id &&
    prev.run.plateBarcode === next.run.plateBarcode &&
    prev.run.analystName === next.run.analystName
  )
}

function AssayRunRowBase({ run, onOpen }: AssayRunRowProps) {
  return (
    <tr className="border-b border-zinc-200 dark:border-zinc-800">
      <td className="px-4 py-3 text-base font-medium text-zinc-900 dark:text-zinc-100">{run.id}</td>
      <td className="px-4 py-3 text-sm tabular-nums text-zinc-600 dark:text-zinc-400">{run.plateBarcode}</td>
      <td className="px-4 py-3 text-sm text-zinc-700 dark:text-zinc-300">{QC_LABELS[run.qcState]}</td>
      <td className="px-4 py-3 text-sm text-zinc-700 dark:text-zinc-300">{run.analystName}</td>
      <td className="px-4 py-3 text-right">
        <button
          type="button"
          onClick={() => onOpen(run.id)}
          className="rounded-md px-4 py-2 text-sm font-medium text-teal-800 hover:bg-teal-50 focus-visible:ring-2 focus-visible:ring-teal-700 focus-visible:ring-offset-2 active:scale-[0.98] dark:text-teal-300 dark:hover:bg-teal-950"
        >
          Open
        </button>
      </td>
    </tr>
  )
}

export const AssayRunRow = memo(AssayRunRowBase, sameRun)

export type QcState = 'released' | 'second_review' | 'on_hold'

export interface AssayRun {
  id: string
  plateBarcode: string
  qcState: QcState
  analystName: string
  readAt: string
}

export interface AssayRunPage {
  rows: AssayRun[]
  nextCursor: string | null
}

