import { fireEvent, render, screen } from '@testing-library/react'
import { describe, expect, it, vi } from 'vitest'

import { AssayRunRow } from './AssayRunRow'
import type { AssayRun } from './types'

const baseRun: AssayRun = {
  id: 'AR-4471',
  plateBarcode: 'PLT-9032-B',
  qcState: 'released',
  analystName: 'Priya Raman',
  readAt: '2026-07-14T09:12:00Z',
}

function renderRow(run: AssayRun) {
  const onOpen = vi.fn()
  const view = render(
    <table>
      <tbody>
        <AssayRunRow run={run} onOpen={onOpen} />
      </tbody>
    </table>,
  )
  return { ...view, onOpen }
}

describe('AssayRunRow', () => {
  it('repaints the QC column when a poll brings a new state on a fresh object', () => {
    const { rerender } = renderRow(baseRun)
    expect(screen.getByText('Released')).toBeInTheDocument()

    rerender(
      <table>
        <tbody>
          <AssayRunRow run={{ ...baseRun, qcState: 'second_review' }} onOpen={vi.fn()} />
        </tbody>
      </table>,
    )

    expect(screen.getByText('Second review')).toBeInTheDocument()
