export interface ExcursionPagePayload {
  status?: string
  rows?: Excursion[]
  nextCursor?: string | null
  reason?: string
}

export type ExcursionPage =
  | { kind: 'page'; rows: Excursion[]; nextCursor: string | null }
  | { kind: 'gap'; reason: string }

export function toExcursionPage(payload: ExcursionPagePayload): ExcursionPage {
  if (!Array.isArray(payload.rows)) {
    return { kind: 'gap', reason: payload.reason ?? 'Chamber log unavailable for this window' }
  }
  return { kind: 'page', rows: payload.rows, nextCursor: payload.nextCursor ?? null }
}

export async function loadExcursionPage(cursor: string | null): Promise<ExcursionPage> {
  const query = cursor ? '?after=' + encodeURIComponent(cursor) : ''
  const response = await fetch('/api/shipments/excursions' + query)
  if (!response.ok) {
    throw new Error('Excursion page request failed with status ' + response.status)
  }
  return toExcursionPage((await response.json()) as ExcursionPagePayload)
}

export function appendPage(loaded: Excursion[], payload: ExcursionPagePayload) {
  const page = toExcursionPage(payload)
  return page.kind === 'gap' ? loaded : [...loaded, ...page.rows]
}

