import { renderHook } from '@testing-library/react'
import { afterEach, describe, expect, it, vi } from 'vitest'

import { useRequestStream } from './useRequestStream'

class FakeEventSource {
  static opened: FakeEventSource[] = []
  closed = false
  listeners = new Map<string, (event: MessageEvent<string>) => void>()

  constructor(public url: string) {
    FakeEventSource.opened.push(this)
  }

  addEventListener(type: string, listener: (event: MessageEvent<string>) => void) {
    this.listeners.set(type, listener)
  }

  removeEventListener(type: string) {
    this.listeners.delete(type)
  }

  close() {
    this.closed = true
  }
}

vi.stubGlobal('EventSource', FakeEventSource)

afterEach(() => {
  FakeEventSource.opened.length = 0
})

describe('useRequestStream', () => {
  it('closes the stream when the board unmounts', () => {
    const { unmount } = renderHook(() => useRequestStream('dsar-5541', vi.fn()))
    unmount()
    expect(FakeEventSource.opened).toHaveLength(1)
    expect(FakeEventSource.opened[0].closed).toBe(true)
  })

  it('closes the old stream before opening the next case', () => {
    const { rerender } = renderHook(({ caseId }) => useRequestStream(caseId, vi.fn()), {
      initialProps: { caseId: 'dsar-5541' },
    })
    rerender({ caseId: 'dsar-5542' })
    expect(FakeEventSource.opened.map((source) => source.closed)).toEqual([true, false])
    expect(FakeEventSource.opened[1].url).toBe('/api/dsar/dsar-5542/stream')
  })
})

