import { useState } from 'react'

import { classifyReading } from './readingExceptions'
import type { ExceptionKind, MeterReading } from './readingExceptions'
import { formatKwh } from './formatKwh'

interface ReadingExceptionSearchProps {
  readings: MeterReading[]
}

const buckets = [
  { value: 'zero-consumption', label: 'Reading zero', hint: 'Panel dead, raise a site visit' },
  { value: 'no-read', label: 'No read taken', hint: 'Meter silent, raise a comms check' },
  { value: 'high-variance', label: 'High variance', hint: 'Read is out by more than 35 percent' },
]

const chipBase =
  'min-h-11 rounded-lg border px-4 py-2 text-sm font-medium transition-colors focus-visible:ring-2 focus-visible:ring-violet-700 focus-visible:ring-offset-2 active:scale-[0.98] motion-reduce:transition-none'

export function ReadingExceptionSearch({ readings }: ReadingExceptionSearchProps) {
  const [bucket, setBucket] = useState<ExceptionKind>('zero-consumption')
  const [query, setQuery] = useState('')

  const needle = query.trim().toLowerCase()
  const matches = readings.filter(
    (reading) =>
      classifyReading(reading) === bucket &&
      (needle.length === 0 ||
        reading.serial.toLowerCase().includes(needle) ||
        reading.siteName.toLowerCase().includes(needle)),
  )
  const activeBucket = buckets.find((option) => option.value === bucket)

  return (
    <section className="mx-auto flex max-w-7xl flex-col gap-6">
      <div className="flex flex-col gap-2">
        <h2 className="text-2xl font-semibold leading-tight text-zinc-900 dark:text-zinc-100">
          Reading exceptions
        </h2>
        <p className="max-w-[65ch] text-base leading-relaxed text-zinc-700 dark:text-zinc-300">
          {activeBucket ? activeBucket.hint : 'Pick an exception type to work through.'}
        </p>
      </div>

      <div className="flex flex-wrap gap-2" role="group" aria-label="Exception type">
        {buckets.map((option) => {
          const isActive = option.value === bucket
          return (
            <button
              key={option.value}
              type="button"
              aria-pressed={isActive}
              onClick={() => setBucket(option.value as ExceptionKind)}
              className={
                isActive
                  ? `${chipBase} border-violet-700 bg-violet-700 text-white hover:bg-violet-800 dark:border-violet-500 dark:bg-violet-600`
                  : `${chipBase} border-zinc-300 text-zinc-900 hover:bg-zinc-50 dark:border-zinc-700 dark:text-zinc-100 dark:hover:bg-zinc-900`
              }
            >
              {option.label}
            </button>
          )
        })}
      </div>

      <div className="flex flex-col gap-2">
        <label htmlFor="exception-query" className="text-sm font-medium text-zinc-700 dark:text-zinc-300">
          Meter serial or site
        </label>
        <input
          id="exception-query"
          type="search"
          value={query}
          onChange={(event) => setQuery(event.target.value)}
          className="rounded-lg border border-zinc-300 bg-white px-4 py-2 text-base text-zinc-900 focus-visible:ring-2 focus-visible:ring-violet-700 focus-visible:ring-offset-2 dark:border-zinc-700 dark:bg-zinc-950 dark:text-zinc-100"
        />
      </div>

      {matches.length === 0 ? (
        <p className="rounded-lg border border-zinc-200 p-6 text-base leading-relaxed text-zinc-700 dark:border-zinc-800 dark:text-zinc-300">
          Nothing in this exception type for that serial or site. Try another exception type.
        </p>
      ) : (
        <table className="w-full border-collapse text-left">
          <caption className="sr-only">Meter reads in the selected exception type</caption>
          <thead>
            <tr className="border-b border-zinc-200 dark:border-zinc-800">
              <th scope="col" className="px-4 py-2 text-sm font-medium text-zinc-600 dark:text-zinc-400">Serial</th>
              <th scope="col" className="px-4 py-2 text-sm font-medium text-zinc-600 dark:text-zinc-400">Site</th>
              <th scope="col" className="px-4 py-2 text-right text-sm font-medium text-zinc-600 dark:text-zinc-400">Consumption</th>
            </tr>
          </thead>
          <tbody>
            {matches.map((reading) => (
              <tr key={reading.serial} className="border-b border-zinc-100 dark:border-zinc-900">
                <td className="px-4 py-3 text-base tabular-nums text-zinc-900 dark:text-zinc-100">{reading.serial}</td>
                <td className="min-w-0 px-4 py-3 text-base text-zinc-900 dark:text-zinc-100">
                  <span className="block truncate" title={reading.siteName}>{reading.siteName}</span>
                </td>
                <td className="px-4 py-3 text-right text-base tabular-nums text-zinc-900 dark:text-zinc-100">
                  {reading.kwh === null ? (
                    <span className="text-zinc-600 dark:text-zinc-400">No read taken</span>
                  ) : (
                    formatKwh(reading.kwh)
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </section>
  )
}

import { render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { describe, expect, it } from 'vitest'

import { classifyReading } from './readingExceptions'
import type { MeterReading } from './readingExceptions'
import { ReadingExceptionSearch } from './ReadingExceptionSearch'

const readings: MeterReading[] = [
  { serial: 'K13-884201', siteName: '4 Ashcombe Terrace', readAt: '2026-07-27T02:10:00Z', kwh: 0, variance: 0 },
  { serial: 'K13-884202', siteName: 'Rowan Court flat 12', readAt: '2026-07-27T02:10:00Z', kwh: null, variance: 0 },
  { serial: 'K13-884203', siteName: 'Barnhill Dairy', readAt: '2026-07-27T02:10:00Z', kwh: 412.5, variance: 0.61 },
]

describe('classifyReading', () => {
  it('separates a true zero read from a meter that never reported', () => {
    expect(classifyReading(readings[0])).toBe('zero-consumption')
    expect(classifyReading(readings[1])).toBe('no-read')
    expect(classifyReading(readings[2])).toBe('high-variance')
  })
})

describe('ReadingExceptionSearch', () => {
  it('lists only the dead panels in the zero reading bucket', () => {
    render(<ReadingExceptionSearch readings={readings} />)
    expect(screen.getByText('4 Ashcombe Terrace')).toBeInTheDocument()
    expect(screen.queryByText('Rowan Court flat 12')).not.toBeInTheDocument()
    expect(screen.getByText('Panel dead, raise a site visit')).toBeInTheDocument()
  })

  it('switches bucket and narrows by serial', async () => {
    const user = userEvent.setup()
    render(<ReadingExceptionSearch readings={readings} />)
    await user.click(screen.getByRole('button', { name: 'No read taken' }))
    expect(screen.getByText('Rowan Court flat 12')).toBeInTheDocument()
    await user.type(screen.getByLabelText('Meter serial or site'), '884299')
    expect(screen.getByText(/Nothing in this exception type/)).toBeInTheDocument()
  })
})

