import { act, renderHook } from '@testing-library/react'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

import { useBulkBarLayout } from './useBulkBarLayout'
import type { BulkBarTheme } from './useBulkBarLayout'

type ChangeListener = (event: MediaQueryListEvent) => void

let listeners: ChangeListener[] = []
let added = 0
let removed = 0

function stubMatchMedia(matches: boolean) {
  listeners = []
  added = 0
  removed = 0
  vi.stubGlobal('matchMedia', (query: string) => ({
    matches,
    media: query,
    addEventListener: (_type: string, listener: ChangeListener) => {
      added += 1
      listeners.push(listener)
    },
    removeEventListener: (_type: string, listener: ChangeListener) => {
      removed += 1
      listeners = listeners.filter((entry) => entry !== listener)
    },
  }))
}

describe('useBulkBarLayout', () => {
  beforeEach(() => stubMatchMedia(true))
  afterEach(() => vi.unstubAllGlobals())

  it('keeps exactly one media listener alive across theme switches', () => {
    const onViewportChange = vi.fn()
    const { rerender } = renderHook(
      ({ theme }: { theme: BulkBarTheme }) => useBulkBarLayout(theme, onViewportChange),
      { initialProps: { theme: 'light' as BulkBarTheme } },
    )

    rerender({ theme: 'dark' })
    rerender({ theme: 'light' })

    expect(added).toBe(1)
    expect(removed).toBe(0)
    expect(listeners).toHaveLength(1)
    expect(document.body.dataset.bulkSheetTheme).toBe('light')
  })

  it('refreshes the alarm list once for one viewport change', () => {
    const onViewportChange = vi.fn()
    renderHook(() => useBulkBarLayout('dark', onViewportChange))

    act(() => {
      listeners.forEach((listener) => listener({ matches: false } as MediaQueryListEvent))
    })

    expect(onViewportChange).toHaveBeenCalledTimes(1)
  })
})

