import { useEffect, useState } from 'react'

import type { ChecklistItem } from './types'

interface ChecklistState {
  items: ChecklistItem[]
  status: 'loading' | 'ready' | 'retrying'
  error: string | null
}

const RETRY_DELAY_MS = 3000

export function useCrewChecklist(crewId: string): ChecklistState {
  const [state, setState] = useState<ChecklistState>({ items: [], status: 'loading', error: null })

  useEffect(() => {
    async function load() {
      try {
        const response = await fetch('/api/crews/' + crewId + '/checklist')
        if (!response.ok) {
          throw new Error('Checklist request failed with ' + response.status)
        }
        const items = (await response.json()) as ChecklistItem[]
        setState({ items, status: 'ready', error: null })
      } catch {
        setState((current) => ({
          ...current,
          status: 'retrying',
          error: 'Cannot reach the crew server. Trying again in 3 seconds.',
        }))
        window.setTimeout(load, RETRY_DELAY_MS)
      }
    }

    load()
  }, [crewId])

  return state
}

