import { useCrewChecklist } from './useCrewChecklist'

interface ChecklistSheetProps {
  crewId: string
  onClose: () => void
}

export function ChecklistSheet({ crewId, onClose }: ChecklistSheetProps) {
  const { items, status, error } = useCrewChecklist(crewId)

  return (
    <section
      aria-label="Crew training checklist"
      className="flex max-h-dvh flex-col gap-6 rounded-t-2xl border-t border-teal-200 bg-white p-4 dark:border-teal-900 dark:bg-teal-950 md:rounded-2xl md:border"
    >
      <div className="flex items-center justify-between gap-4">
        <h2 className="text-lg font-semibold text-teal-950 dark:text-teal-50">Training checklist</h2>
        <button
          type="button"
          onClick={onClose}
          className="min-h-11 rounded-lg px-4 py-2 text-base font-medium text-teal-900 hover:bg-teal-50 focus-visible:ring-2 focus-visible:ring-teal-700 focus-visible:ring-offset-2 active:scale-[0.98] dark:text-teal-100 dark:hover:bg-teal-900"
        >
          Close
        </button>
      </div>
      {status === 'retrying' && error !== null ? (
        <p role="status" className="text-base text-amber-800 dark:text-amber-300">
          {error}
        </p>
      ) : null}
      <ul className="flex flex-col gap-2">
        {items.map((item) => (
          <li key={item.id} className="flex min-h-11 items-center gap-4 text-base text-teal-950 dark:text-teal-50">
            {item.label}
          </li>
        ))}
      </ul>
    </section>
  )
}

