useEffect(() => {
  let dropped = false
  let retryTimer = 0

  async function load() {
    try {
      const response = await fetch('/api/crews/' + crewId + '/checklist')
      if (!response.ok) {
        throw new Error('Checklist request failed with ' + response.status)
      }
      const items = (await response.json()) as ChecklistItem[]
      if (dropped) {
        return
      }
      setState({ items, status: 'ready', error: null })
    } catch {
      if (dropped) {
        return
      }
      setState((current) => ({
        ...current,
        status: 'retrying',
        error: 'Cannot reach the crew server. Trying again in 3 seconds.',
      }))
      retryTimer = window.setTimeout(load, RETRY_DELAY_MS)
    }
  }

  load()

  return () => {
    dropped = true
    window.clearTimeout(retryTimer)
  }
