import { act, renderHook, waitFor } from '@testing-library/react'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

import { useCrewChecklist } from './useCrewChecklist'

describe('useCrewChecklist', () => {
  beforeEach(() => {
    vi.useFakeTimers({ shouldAdvanceTime: true })
    vi.stubGlobal('fetch', vi.fn(() => Promise.reject(new Error('offline'))))
  })

  afterEach(() => {
    vi.useRealTimers()
    vi.unstubAllGlobals()
  })

  it('stops retrying once the caller has unmounted', async () => {
    const { result, unmount } = renderHook(() => useCrewChecklist('crew-77'))
    await waitFor(() => expect(result.current.status).toBe('retrying'))
    expect(fetch).toHaveBeenCalledTimes(1)

    unmount()
    await act(async () => {
      vi.advanceTimersByTime(9000)
    })

    expect(fetch).toHaveBeenCalledTimes(1)
  })

  it('keeps retrying while it is still mounted', async () => {
    renderHook(() => useCrewChecklist('crew-77'))
    await waitFor(() => expect(fetch).toHaveBeenCalledTimes(1))

    await act(async () => {
      vi.advanceTimersByTime(3000)
    })

    await waitFor(() => expect(fetch).toHaveBeenCalledTimes(2))
  })
})

