import { useMemo, useState } from 'react'

import type { HarvestBlock } from '../types'

interface BlockFilterSheetProps {
  blocks: HarvestBlock[]
  selectedIds: string[]
  onToggle: (blockId: string) => void
  onApply: () => void
}

export function BlockFilterSheet({ blocks, selectedIds, onToggle, onApply }: BlockFilterSheetProps) {
  const [query, setQuery] = useState('')

  const visible = useMemo(() => {
    const needle = query.trim().toLowerCase()
    if (needle === '') {
      return blocks
    }
    return blocks.filter((block) => !block.name.toLowerCase().includes(needle))
  }, [blocks, query])

  return (
    <section
      aria-label="Filter harvest blocks"
      className="flex max-h-dvh flex-col gap-6 rounded-t-2xl border-t border-stone-200 bg-white p-4 dark:border-stone-800 dark:bg-stone-950 md:rounded-2xl md:border"
    >
      <div className="flex flex-col gap-2">
        <label htmlFor="block-search" className="text-sm font-medium text-stone-700 dark:text-stone-300">
          Search blocks
        </label>
        <input
          id="block-search"
          type="search"
          value={query}
          onChange={(event) => setQuery(event.target.value)}
          className="rounded-lg border border-stone-300 px-4 py-2 text-sm text-stone-900 focus-visible:ring-2 focus-visible:ring-emerald-700 focus-visible:ring-offset-2 dark:border-stone-700 dark:bg-stone-900 dark:text-stone-100"
        />
      </div>
      <ul className="flex flex-col gap-2 overflow-y-auto">
        {visible.map((block) => (
          <li key={block.id}>
            <label className="flex min-h-11 items-center gap-4 rounded-lg border border-stone-200 px-4 py-3 text-base text-stone-900 hover:bg-stone-50 dark:border-stone-800 dark:text-stone-100 dark:hover:bg-stone-900">
              <input
                type="checkbox"
                checked={selectedIds.includes(block.id)}
                onChange={() => onToggle(block.id)}
                className="size-4 focus-visible:ring-2 focus-visible:ring-emerald-700 focus-visible:ring-offset-2"
              />
              <span className="min-w-0 flex-1 truncate" title={block.name}>{block.name}</span>
              <span className="text-sm tabular-nums text-stone-600 dark:text-stone-400">{block.hectares} ha</span>
            </label>
          </li>
        ))}
        {visible.length === 0 ? (
          <li className="px-4 py-6 text-base text-stone-600 dark:text-stone-400">
            Nothing matches that search. Clear the box to bring back all {blocks.length} blocks.
          </li>
        ) : null}
      </ul>
      <button
        type="button"
        onClick={onApply}
        className="min-h-11 rounded-lg bg-emerald-700 px-4 py-2 text-base font-medium text-white hover:bg-emerald-800 focus-visible:ring-2 focus-visible:ring-emerald-700 focus-visible:ring-offset-2 active:scale-[0.98] disabled:pointer-events-none disabled:opacity-50 dark:bg-emerald-600 dark:hover:bg-emerald-500"
      >
        Apply filters
      </button>
    </section>
  )
}

