import { fireEvent, render, screen } from '@testing-library/react'
import { describe, expect, it, vi } from 'vitest'

import { BlockFilterSheet } from './BlockFilterSheet'

const blocks = [
  { id: 'blk-118', name: 'Sawyer Ridge 3', hectares: 41.6 },
  { id: 'blk-204', name: 'Cold Creek Flat', hectares: 12.3 },
  { id: 'blk-311', name: 'Ridge Landing', hectares: 27.9 },
]

function rowLabels() {
  return screen.getAllByRole('checkbox').map((box) => box.closest('label')?.textContent ?? '')
}

describe('BlockFilterSheet', () => {
  it('keeps the blocks whose name contains the search text', () => {
    render(<BlockFilterSheet blocks={blocks} selectedIds={[]} onToggle={vi.fn()} onApply={vi.fn()} />)
    fireEvent.change(screen.getByLabelText('Search blocks'), { target: { value: 'ridge' } })
    const labels = rowLabels()
    expect(labels).toHaveLength(2)
    expect(labels[0]).toContain('Sawyer Ridge 3')
    expect(labels[1]).toContain('Ridge Landing')
  })

  it('lists every block when the search box is empty', () => {
    render(<BlockFilterSheet blocks={blocks} selectedIds={[]} onToggle={vi.fn()} onApply={vi.fn()} />)
    expect(screen.getAllByRole('checkbox')).toHaveLength(3)
  })
})

