import { useState } from 'react'

import { assignCallsToBerth, fetchOccupancy } from './occupancyApi'
import type { BerthOccupancy, PortCall } from './types'

interface BulkBerthAssignDialogProps {
  berthId: string
  berthLabel: string
  selectedCalls: PortCall[]
  onOccupancyChange: (occupancy: BerthOccupancy) => void
  onClose: () => void
}

export function BulkBerthAssignDialog({
  berthId,
  berthLabel,
  selectedCalls,
  onOccupancyChange,
  onClose,
}: BulkBerthAssignDialogProps) {
  const [pending, setPending] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const callIds = selectedCalls.map((call) => call.id)

  function handleConfirm() {
    setPending(true)
    setError(null)
    assignCallsToBerth(berthId, callIds)
    fetchOccupancy(berthId)
      .then((occupancy) => {
        onOccupancyChange(occupancy)
        onClose()
      })
      .catch(() => {
        setError('The berth assignment did not go through. No calls were moved.')
        setPending(false)
      })
  }

  return (
    <section
      aria-labelledby="bulk-berth-heading"
      className="flex w-full max-w-md flex-col gap-6 rounded-lg border border-slate-200 bg-white p-6 dark:border-slate-800 dark:bg-slate-950"
    >
      <h2 id="bulk-berth-heading" className="text-lg font-semibold leading-tight text-slate-900 dark:text-slate-100">
        Assign to {berthLabel}
      </h2>
      <ul className="flex flex-col gap-2">
        {selectedCalls.map((call) => (
          <li key={call.id} className="flex items-center justify-between gap-4">
            <span className="min-w-0 flex-1 truncate text-base text-slate-800 dark:text-slate-200" title={call.vesselName}>
              {call.vesselName}
            </span>
            <span className="text-sm tabular-nums text-slate-600 dark:text-slate-400">{call.etaLocal}</span>
          </li>
        ))}
      </ul>
      {error === null ? null : (
        <p role="alert" className="text-base text-rose-700 dark:text-rose-400">
          {error}
        </p>
      )}
      <div className="flex items-center gap-4">
        <button
          type="button"
          onClick={handleConfirm}
          disabled={pending}
          className="rounded-md bg-teal-800 px-4 py-2 text-base font-medium text-white transition-colors hover:bg-teal-900 focus-visible:ring-2 focus-visible:ring-teal-700 focus-visible:ring-offset-2 active:scale-[0.98] disabled:pointer-events-none disabled:opacity-50 motion-reduce:transition-none dark:bg-teal-700 dark:hover:bg-teal-600"
        >
          {pending ? 'Assigning...' : selectedCalls.length === 1 ? 'Assign 1 call' : 'Assign ' + selectedCalls.length + ' calls'}
        </button>
        <button
          type="button"
          onClick={onClose}
          className="rounded-md border border-slate-300 px-4 py-2 text-base font-medium text-slate-800 transition-colors hover:bg-slate-50 focus-visible:ring-2 focus-visible:ring-teal-700 focus-visible:ring-offset-2 dark:border-slate-700 dark:text-slate-200 dark:hover:bg-slate-900"
        >
          Cancel
        </button>
      </div>
    </section>
  )
}

import type { BerthOccupancy } from './types'

const BASE = '/api/berths'

export async function assignCallsToBerth(berthId: string, callIds: string[]): Promise<void> {
  const response = await fetch(BASE + '/' + berthId + '/calls', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ callIds }),
  })
  if (!response.ok) {
    throw new Error('Berth assignment rejected with ' + response.status)
  }
}

export async function fetchOccupancy(berthId: string): Promise<BerthOccupancy> {
  const response = await fetch(BASE + '/' + berthId + '/occupancy')
  if (!response.ok) {
    throw new Error('Occupancy read rejected with ' + response.status)
  }
  return (await response.json()) as BerthOccupancy
}

