import { useState } from 'react'
import { QueueRow } from './QueueRow'

interface PhotoQueueProps {
  onQueueChange: (files: File[]) => void
}

export function PhotoQueue({ onQueueChange }: PhotoQueueProps) {
  const [queue, setQueue] = useState<File[]>([])

  const addPhotos = (incoming: File[]) => {
    const fresh = incoming.filter((file) => !queue.includes(file))
    const next = [...queue, ...fresh]
    setQueue(next)
    onQueueChange(next)
  }

  return (
    <section className="flex flex-col gap-4">
      <label htmlFor="diary-photos" className="text-sm font-medium text-zinc-700 dark:text-zinc-300">
        Add site photos
      </label>
      <input
        id="diary-photos"
        type="file"
        accept="image/*"
        multiple
        onChange={(event) => addPhotos(Array.from(event.target.files ?? []))}
        className="text-sm text-zinc-600 dark:text-zinc-400"
      />
      {queue.length === 0 ? (
        <p className="text-sm text-zinc-500 dark:text-zinc-400">No photos queued yet. Add today's site photos to start the entry.</p>
      ) : (
        <ul className="flex flex-col gap-2">
          {queue.map((file) => (
            <QueueRow key={file.name + file.lastModified} file={file} />
          ))}
        </ul>
      )}
    </section>
  )
}

