    expect(screen.getAllByRole('listitem')).toHaveLength(1)
  })

  it('keeps two different photos that happen to share a camera filename', () => {
    render(<PhotoQueue onQueueChange={vi.fn()} />)
    const input = screen.getByLabelText('Add site photos')
    pick(input, [new File(['jpeg-a'], 'IMG_0311.jpg', { type: 'image/jpeg', lastModified: 1721810400000 })])
    pick(input, [new File(['jpeg-b-longer'], 'IMG_0311.jpg', { type: 'image/jpeg', lastModified: 1721824000000 })])
    expect(screen.getAllByRole('listitem')).toHaveLength(2)
  })
})

