const DAY_MS = 24 * 60 * 60 * 1000

/**
 * Week index for a staged flag ramp, counted from the day the ramp started.
 */
export function rampWeek(startedAt: Date, now: Date): number {
  const elapsedDays = Math.floor((now.getTime() - startedAt.getTime()) / DAY_MS)
  if (elapsedDays < 0) {
    return 0
  }

  return Math.floor(elapsedDays / 7)
}

