import { describe, expect, it } from 'vitest'

import { rampWeek } from './rampWeek'

// 2 April 2026 is a Thursday, the mid-week start from the ticket.
const startedAt = new Date('2026-04-02T08:00:00Z')

describe('rampWeek', () => {
  it('reads week 1 on the day the ramp starts', () => {
    expect(rampWeek(startedAt, new Date('2026-04-02T16:30:00Z'))).toBe(1)
  })

  it('stays on week 1 for the first seven days', () => {
    expect(rampWeek(startedAt, new Date('2026-04-08T08:00:00Z'))).toBe(1)
  })

  it('moves to week 2 exactly seven days in', () => {
    expect(rampWeek(startedAt, new Date('2026-04-09T08:00:00Z'))).toBe(2)
  })

  it('reaches week 6 in the last week of a six week ramp', () => {
    expect(rampWeek(startedAt, new Date('2026-05-07T08:00:00Z'))).toBe(6)
  })
})
